// Package source hosts source adapters: the code that watches the outside
// world and emits normalized Events. v0.1's only ingress was POST /api/events;
// the HTTP poller adds pull-based ingestion for feeds and APIs that have no
// webhooks. A poller is deliberately dumb: it fetches, normalizes items into
// Events, and hands each one to the ordinary Ingest pipeline — it never
// interprets, filters, or routes.
//
// Concurrency contract: one goroutine per source, owned by Run, bounded by
// the context, exited when the context is canceled. Polls within one source
// are strictly serial, so cursor state needs no locking beyond SQLite's.
package source

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

// HTTPPoller polls a JSON endpoint on an interval and ingests each record
// as an Event. Cursor semantics are lazy on purpose: every item is offered
// to InsertEvent on every poll and dedup drops what was seen, so correctness
// never depends on ordering assumptions. The persisted cursor exists for
// cursor-based APIs (URL substitution) and as a restart watermark, not as
// the dedup mechanism.
type HTTPPoller struct {
	cfg    config.Source
	urlTpl *template.Template
	client *http.Client
	// bearer is resolved once from the environment at construction; it is
	// never persisted, logged, or copied anywhere but the request header.
	bearer string
}

// NewHTTPPoller validates and prepares a poller. The bearer token is read
// from the environment once, here: it must exist at startup (fail loudly)
// and must never be persisted or logged.
func NewHTTPPoller(cfg config.Source) (*HTTPPoller, error) {
	tpl, err := template.New("url").Parse(cfg.URL)
	if err != nil {
		return nil, fmt.Errorf("source %s: bad url template: %w", cfg.Name, err)
	}
	bearer, err := bearerFromEnv(cfg.BearerTokenEnv)
	if err != nil {
		return nil, fmt.Errorf("source %s: %w", cfg.Name, err)
	}
	return &HTTPPoller{
		cfg:    cfg,
		urlTpl: tpl,
		// Outbound polls must be bounded: a hung target must not stall the
		// poll loop's single goroutine forever.
		client: &http.Client{Timeout: 15 * time.Second},
		bearer: bearer,
	}, nil
}

// Run polls until ctx is canceled. The first poll is immediate so a fresh
// config produces data without waiting one interval.
func (p *HTTPPoller) Run(ctx context.Context, rt *runtime.Runtime) {
	ticker := time.NewTicker(p.cfg.Every)
	defer ticker.Stop()

	p.poll(ctx, rt)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			p.poll(ctx, rt)
		}
	}
}

// poll is one fetch-normalize-ingest cycle. Every error path is a log line,
// never a crash: a broken feed must not take down the runtime, and the next
// tick retries anyway.
func (p *HTTPPoller) poll(ctx context.Context, rt *runtime.Runtime) {
	// If the fetch itself is canceled by shutdown, nothing was ingested and
	// the cursor is unchanged — safe to abandon mid-flight.
	items, err := p.fetch(ctx, rt.DB)
	if err != nil {
		log.Printf("mrmr: poll %s: fetch failed: %v", p.cfg.Name, err)
		return
	}

	var ingested, dups, cursorAdvanced int
	newCursor := ""
	for i, item := range items {
		if ctx.Err() != nil {
			return // shutdown: remaining items wait for the next poll
		}
		obj, ok := item.(map[string]any)
		if !ok {
			log.Printf("mrmr: poll %s: item %d is not an object, skipped", p.cfg.Name, i)
			continue
		}
		if c := cursorValue(obj, p.cfg.CursorField); c != "" {
			if c > newCursor { // ponytail: string max; numeric ordering only matters for {{.cursor}} substitution
				newCursor = c
			}
		}
		e, err := p.normalize(obj)
		if err != nil {
			log.Printf("mrmr: poll %s: item %d: %v", p.cfg.Name, i, err)
			continue
		}
		resp, err := rt.Ingest(ctx, e)
		if err != nil {
			log.Printf("mrmr: poll %s: ingest %s failed: %v", p.cfg.Name, e.ID, err)
			continue
		}
		if resp.Duplicate {
			dups++
		} else {
			ingested++
		}
	}

	// Advance the watermark only after the batch is offered: a crash
	// mid-poll re-polls the same window, and dedup makes that harmless.
	if newCursor != "" && newCursor != p.cursor(rt.DB) {
		if err := rt.DB.SetCursor(p.cfg.Name, newCursor); err != nil {
			log.Printf("mrmr: poll %s: persist cursor failed: %v", p.cfg.Name, err)
		} else {
			cursorAdvanced = 1
		}
	}
	log.Printf("mrmr: poll %s: %d items: %d new, %d duplicate, cursor=%s",
		p.cfg.Name, len(items), ingested, dups, map[bool]string{true: newCursor, false: "unchanged"}[cursorAdvanced == 1])
}

// fetch retrieves and extracts the item array. The cursor is substituted
// into the URL template when present so cursor-based APIs page correctly;
// plain feeds ignore it.
func (p *HTTPPoller) fetch(ctx context.Context, db *storage.DB) ([]any, error) {
	var urlBuf bytes.Buffer
	if err := p.urlTpl.Execute(&urlBuf, map[string]any{"cursor": p.cursor(db)}); err != nil {
		return nil, fmt.Errorf("render url: %w", err)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, urlBuf.String(), nil)
	if err != nil {
		return nil, err
	}
	if p.bearer != "" {
		req.Header.Set("Authorization", "Bearer "+p.bearer)
	}
	resp, err := p.client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	// Feeds are small; 4 MiB caps a hostile or misconfigured target.
	body, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if err != nil {
		return nil, err
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return nil, fmt.Errorf("status %d", resp.StatusCode)
	}

	var doc any
	if err := json.Unmarshal(body, &doc); err != nil {
		return nil, fmt.Errorf("decode JSON: %w", err)
	}
	items := doc
	if p.cfg.ItemPath != "" {
		items = doc
		for _, part := range strings.Split(p.cfg.ItemPath, ".") {
			m, ok := items.(map[string]any)
			if !ok {
				return nil, fmt.Errorf("item_path %q: %s is not an object", p.cfg.ItemPath, part)
			}
			items = m[part]
		}
	}
	list, ok := items.([]any)
	if !ok {
		if items == nil {
			return nil, nil // absent path is an empty poll, not an error
		}
		return nil, fmt.Errorf("item_path %q did not resolve to an array", p.cfg.ItemPath)
	}
	return list, nil
}

// normalize turns one fetched record into an Event. The whole record becomes
// data — the core makes no assumptions about source payloads, and dropping
// fields here would silently erase exactly the context the interpreter needs.
// The cursor field doubles as source_event_id, which is what makes dedup work.
func (p *HTTPPoller) normalize(item map[string]any) (event.Event, error) {
	e := event.Event{
		ID:        event.NewID("evt_"),
		Type:      p.cfg.EventType,
		Source:    p.cfg.Name,
		Timestamp: time.Now().UTC(),
		Data:      item,
	}
	if p.cfg.SubjectField != "" {
		if v, ok := item[p.cfg.SubjectField]; ok {
			e.Subject = fmt.Sprint(v)
		}
	}
	if p.cfg.TimestampField != "" {
		if v, ok := item[p.cfg.TimestampField].(string); ok {
			if ts, perr := time.Parse(time.RFC3339, v); perr == nil {
				e.Timestamp = ts.UTC()
			}
			// Unparseable timestamps keep "now": a wrong-but-present event
			// beats a dropped one for ambient feeds.
		}
	}
	if p.cfg.CursorField != "" {
		if c := cursorValue(item, p.cfg.CursorField); c != "" {
			e.Metadata = map[string]any{"source_event_id": c}
		} else {
			return e, fmt.Errorf("cursor_field %q missing; item cannot be deduplicated", p.cfg.CursorField)
		}
	}
	return e, nil
}

func cursorValue(item map[string]any, field string) string {
	if field == "" {
		return ""
	}
	if v, ok := item[field]; ok {
		return fmt.Sprint(v)
	}
	return ""
}

// cursor reads the persisted watermark. An unknown source is a fresh poller:
// empty cursor, and the URL template renders without one.
func (p *HTTPPoller) cursor(db *storage.DB) string {
	c, err := db.Cursor(p.cfg.Name)
	if err != nil {
		log.Printf("mrmr: poll %s: read cursor: %v", p.cfg.Name, err)
	}
	return c
}

// bearerFromEnv resolves the bearer_token_env reference at startup.
func bearerFromEnv(name string) (string, error) {
	if name == "" {
		return "", nil
	}
	v, ok := os.LookupEnv(name)
	if !ok || v == "" {
		return "", fmt.Errorf("env %s (bearer_token_env) is not set", name)
	}
	return v, nil
}

// Poller tests run the full loop against real HTTP servers: a feed server
// standing in for the polled target and the standard mock OpenAI-compatible
// model behind a real SQLite database. The invariants that matter: items
// become events exactly once across repeated polls (dedup, not the cursor,
// is the correctness mechanism), the cursor is persisted and substituted
// into subsequent fetches, and malformed items are skipped without killing
// the poll.
package source

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"sync/atomic"
	"testing"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

// modelMock returns the standard canned OpenAI-compatible response. Every
// ingested item scores unimportant so the pipeline ends in ignore and the
// tests stay quiet.
func modelMock(t *testing.T) (url string, calls *atomic.Int32) {
	t.Helper()
	var n atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n.Add(1)
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]any{
			"choices": []any{map[string]any{
				"message": map[string]any{"content": `{"category":"unimportant","importance":0.1}`},
			}},
		})
	}))
	t.Cleanup(srv.Close)
	return srv.URL, &n
}

func testRuntime(t *testing.T, modelURL string) *runtime.Runtime {
	t.Helper()
	db, err := storage.Open(filepath.Join(t.TempDir(), "poller.db"))
	if err != nil {
		t.Fatalf("open storage: %v", err)
	}
	t.Cleanup(func() { db.Close() })
	return &runtime.Runtime{
		DB:       db,
		Client:   &model.Client{},
		ModelCfg: model.Config{Provider: "openai-compatible", BaseURL: modelURL, Model: "mock-model"},
		ModelKey: "mock",
		Prompt:   "classify this event",
		Schema: model.Schema{
			"category":   {Type: "string", Enum: []any{"unimportant"}},
			"importance": {Type: "number"},
		},
		Policy: mustPolicy(),
	}
}

// mustPolicy keeps the struct literal out of every test runtime construction.
func mustPolicy() policy.Policy {
	return policy.Policy{Default: policy.Then{Ignore: true}}
}

func pollerCfg(url string) config.Source {
	return config.Source{
		Name:        "feed",
		Type:        "http-poller",
		URL:         url,
		Every:       time.Minute, // Run is never entered in tests; poll is called directly
		ItemPath:    "items",
		CursorField: "id",
		EventType:   "feed.item.published",
	}
}

func feedServer(t *testing.T, pages ...string) (url string, gotQuery *atomic.Value) {
	t.Helper()
	var n atomic.Int32
	var q atomic.Value
	q.Store("")
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		i := int(n.Add(1)) - 1
		q.Store(r.URL.RawQuery)
		page := pages[len(pages)-1]
		if i < len(pages) {
			page = pages[i]
		}
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, page)
	}))
	t.Cleanup(srv.Close)
	return srv.URL, &q
}

func countEvents(t *testing.T, rt *runtime.Runtime) int {
	t.Helper()
	var n int
	if err := rt.DB.QueryRow(`SELECT COUNT(*) FROM events`).Scan(&n); err != nil {
		t.Fatalf("count events: %v", err)
	}
	return n
}

// TestPollerIngestsEachItemOnce is the core loop: two items become two
// events with a model call each; repolling the same feed adds nothing
// because dedup drops them before the model; a changed feed adds only the
// new item. The cursor must be persisted across the polls.
func TestPollerIngestsEachItemOnce(t *testing.T) {
	modelURL, modelCalls := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[
		{"id":"a","title":"first"},
		{"id":"b","title":"second"}]}`,
		`{"items":[
		{"id":"a","title":"first"},
		{"id":"b","title":"second"},
		{"id":"c","title":"third"}]}`)

	rt := testRuntime(t, modelURL)
	p, err := NewHTTPPoller(pollerCfg(feedURL))
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}
	ctx := context.Background()

	p.poll(ctx, rt)
	if got := countEvents(t, rt); got != 2 {
		t.Errorf("events after first poll = %d, want 2", got)
	}
	if modelCalls.Load() != 2 {
		t.Errorf("model calls after first poll = %d, want 2", modelCalls.Load())
	}
	if c, _ := rt.DB.Cursor("feed"); c != "b" {
		t.Errorf("cursor after first poll = %q, want b", c)
	}

	p.poll(ctx, rt)
	if got := countEvents(t, rt); got != 3 {
		t.Errorf("events after second poll = %d, want 3 (only the new item)", got)
	}
	// Dedup happens at InsertEvent, before any model call — repolling a
	// known feed must cost no inference.
	if modelCalls.Load() != 3 {
		t.Errorf("model calls after second poll = %d, want 3", modelCalls.Load())
	}
	if c, _ := rt.DB.Cursor("feed"); c != "c" {
		t.Errorf("cursor after second poll = %q, want c", c)
	}
}

// TestPollerSubstitutesCursorIntoURL pins the cursor-based-API case: the
// first fetch has no cursor, later fetches carry the persisted one.
func TestPollerSubstitutesCursorIntoURL(t *testing.T) {
	modelURL, _ := modelMock(t)
	feedURL, gotQuery := feedServer(t, `{"items":[{"id":"a"}]}`)

	rt := testRuntime(t, modelURL)
	cfg := pollerCfg(feedURL + "?after={{ .cursor }}")
	p, err := NewHTTPPoller(cfg)
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}

	p.poll(context.Background(), rt)
	if q := gotQuery.Load().(string); q != "after=" {
		t.Errorf("first poll query = %q, want empty after", q)
	}
	p.poll(context.Background(), rt)
	if q := gotQuery.Load().(string); q != "after=a" {
		t.Errorf("second poll query = %q, want after=a", q)
	}
}

// TestPollerNormalizesItemFields covers the mapping knobs: subject and
// RFC3339 timestamp come from the item, source_event_id comes from the
// cursor field, and the whole item is preserved as data.
func TestPollerNormalizesItemFields(t *testing.T) {
	modelURL, _ := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[
		{"id":"x1","title":"Disk full","published":"2026-09-07T12:00:00Z","disk":"nvme0"}]}`)

	rt := testRuntime(t, modelURL)
	cfg := pollerCfg(feedURL)
	cfg.SubjectField = "title"
	cfg.TimestampField = "published"
	p, err := NewHTTPPoller(cfg)
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}

	p.poll(context.Background(), rt)
	// QueryRow, not Query: the pool is a single connection (SetMaxOpenConns(1)),
	// so an open rows iterator would deadlock Inspect below.
	var id string
	if err := rt.DB.QueryRow(`SELECT id FROM events WHERE source = 'feed' LIMIT 1`).Scan(&id); err != nil {
		t.Fatalf("query event: %v", err)
	}
	ins, err := rt.DB.Inspect(id)
	if err != nil {
		t.Fatalf("inspect: %v", err)
	}
	e := ins.Event
	if e.Subject != "Disk full" {
		t.Errorf("subject = %q, want Disk full", e.Subject)
	}
	if e.Type != "feed.item.published" {
		t.Errorf("type = %q, want feed.item.published", e.Type)
	}
	if want := time.Date(2026, 9, 7, 12, 0, 0, 0, time.UTC); !e.Timestamp.Equal(want) {
		t.Errorf("timestamp = %v, want item's %v", e.Timestamp, want)
	}
	if e.Data["disk"] != "nvme0" {
		t.Errorf("data = %v, want the whole item preserved", e.Data)
	}
}

// TestPollerSkipsItemsWithoutCursorField pins the fail-closed dedup rule:
// when cursor_field is configured, an item without it cannot be identified
// and must not be ingested (payload-hash dedup would not catch a changing
// payload, so ingest would duplicate).
func TestPollerSkipsItemsWithoutCursorField(t *testing.T) {
	modelURL, modelCalls := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[
		{"title":"no id here"},
		{"id":"ok","title":"fine"}]}`)

	rt := testRuntime(t, modelURL)
	p, err := NewHTTPPoller(pollerCfg(feedURL))
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}

	p.poll(context.Background(), rt)
	if got := countEvents(t, rt); got != 1 {
		t.Errorf("events = %d, want 1 (only the identified item)", got)
	}
	if modelCalls.Load() != 1 {
		t.Errorf("model calls = %d, want 1", modelCalls.Load())
	}
}

// TestPollerFetchFailureKeepsState: a dead target must not crash, ingest
// nothing, or move the cursor; the next tick retries.
func TestPollerFetchFailureKeepsState(t *testing.T) {
	modelURL, _ := modelMock(t)
	rt := testRuntime(t, modelURL)
	rt.DB.SetCursor("feed", "old")

	p, err := NewHTTPPoller(pollerCfg("http://127.0.0.1:1/feed"))
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}
	p.poll(context.Background(), rt) // port 1: connection refused

	if got := countEvents(t, rt); got != 0 {
		t.Errorf("events = %d, want 0", got)
	}
	if c, _ := rt.DB.Cursor("feed"); c != "old" {
		t.Errorf("cursor = %q, want unchanged old", c)
	}
}

// TestCursorSurvivesReopen pins the restart-safety story: the watermark
// lives in SQLite, so a restarted runtime resumes where it left off.
func TestCursorSurvivesReopen(t *testing.T) {
	path := filepath.Join(t.TempDir(), "cursor.db")
	db1, err := storage.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := db1.SetCursor("feed", "42"); err != nil {
		t.Fatal(err)
	}
	db1.Close()

	db2, err := storage.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer db2.Close()
	if c, err := db2.Cursor("feed"); err != nil || c != "42" {
		t.Errorf("cursor after reopen = %q, %v, want 42", c, err)
	}
	if c, err := db2.Cursor("unknown"); err != nil || c != "" {
		t.Errorf("unknown source cursor = %q, %v, want empty, nil", c, err)
	}
}

// TestRunStopsOnContextCancel is the goroutine-contract check: Run owns one
// goroutine, exits when ctx is canceled, and does it promptly.
func TestRunStopsOnContextCancel(t *testing.T) {
	modelURL, _ := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[]}`)
	rt := testRuntime(t, modelURL)
	cfg := pollerCfg(feedURL)
	cfg.Every = 50 * time.Millisecond // fast ticks; feed returns no items
	p, err := NewHTTPPoller(cfg)
	if err != nil {
		t.Fatal(err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { p.Run(ctx, rt); close(done) }()
	time.Sleep(120 * time.Millisecond) // let at least one tick pass
	cancel()

	select {
	case <-done:
		// stopped promptly
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not stop after context cancel")
	}
}

// Package config loads and validates the mrmr YAML config. Validation happens
// before anything is activated: an invalid config must fail startup loudly
// rather than produce a runtime that silently misbehaves (a policy with no
// then, a model that doesn't exist). Config is the only place mrmr's behavior
// is described, so it is also the first place to look when behavior surprises.
package config

import (
	"bytes"
	"fmt"
	"math"
	"os"
	"time"

	"gopkg.in/yaml.v3"

	"github.com/heath0xff/mrmr/internal/filter"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
)

type Server struct {
	Addr string `yaml:"addr"`
}

type DB struct {
	Path string `yaml:"path"`
}

type Interpret struct {
	Model  string       `yaml:"model"`
	Prompt string       `yaml:"prompt"`
	Schema model.Schema `yaml:"schema"`
}

// Source configures one data source adapter. v0.1 ships one type:
// http-poller, which fetches a JSON endpoint on an interval and ingests each
// record as an Event. BearerTokenEnv names an environment variable — the
// token itself never lives in this file — and is resolved once at startup.
type Source struct {
	Name           string        `yaml:"name"`
	Type           string        `yaml:"type"`
	URL            string        `yaml:"url"`              // may reference {{ .cursor }}
	Every          time.Duration `yaml:"every"`            // min 1s: protects the polled target
	BearerTokenEnv string        `yaml:"bearer_token_env"` // optional
	ItemPath       string        `yaml:"item_path"`        // optional dot-path to the record array
	CursorField    string        `yaml:"cursor_field"`     // optional; dedup id + watermark
	SubjectField   string        `yaml:"subject_field"`    // optional
	TimestampField string        `yaml:"timestamp_field"`  // optional; RFC3339
	EventType      string        `yaml:"event_type"`
}

// Agent is a delegation target. v0.1 ships only the generic HTTP adapter,
// so there is no type field yet: every agent is an HTTP endpoint that
// receives {event_id, decision, prompt} and returns 2xx.
type Agent struct {
	Endpoint string `yaml:"endpoint"`
}

type Config struct {
	Server Server `yaml:"server"`
	DB     DB     `yaml:"db"`
	// Filter is the pre-model gate (IMPLEMENTATION.md section 3):
	// deterministic checks that run before any model call. An event
	// that fails any Spec is recorded and ignored before
	// interpretation.
	Filter    filter.List             `yaml:"filter"`
	Models    map[string]model.Config `yaml:"models"`
	Interpret Interpret               `yaml:"interpret"`
	// Policy is inlined so the YAML reads exactly like IMPLEMENTATION.md:
	// a top-level `policy:` list plus a sibling `default:`.
	Policy policy.Policy `yaml:"policy,inline"`
	// Agents are delegation targets referenced by name from policy rules.
	// Endpoints live here, not in policy, so policies stay readable and
	// agent locations change without touching rule logic.
	Agents map[string]Agent `yaml:"agents"`
	// Sources are pull-based ingesters; each runs its own goroutine and
	// feeds the same pipeline as POST /api/events.
	Sources []Source `yaml:"sources"`
}

// Load reads, parses, and validates the config at path. Defaults (addr,
// db path) are applied for the values a minimal local setup never needs to
// set; anything the runtime cannot run correctly without stays required.
// Decoding is strict — unknown keys are errors, not warnings — because a
// typo like `api_keyenv:` silently disabling auth is far worse than a
// refused startup.
func Load(path string) (*Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read config %s: %w", path, err)
	}
	var c Config
	d := yaml.NewDecoder(bytes.NewReader(b))
	d.KnownFields(true)
	if err := d.Decode(&c); err != nil {
		return nil, fmt.Errorf("parse config %s: %w", path, err)
	}
	if c.Server.Addr == "" {
		c.Server.Addr = ":4242"
	}
	if c.DB.Path == "" {
		c.DB.Path = "mrmr.db"
	}
	if err := c.Validate(); err != nil {
		return nil, err
	}
	return &c, nil
}

func (c *Config) Validate() error {
	if c.Interpret.Model == "" {
		return fmt.Errorf("config: interpret.model is required")
	}
	mc, ok := c.Models[c.Interpret.Model]
	if !ok {
		return fmt.Errorf("config: interpret.model %q not defined in models", c.Interpret.Model)
	}
	if mc.Provider != "openai-compatible" {
		return fmt.Errorf("config: model %q: unsupported provider %q (v0.1: openai-compatible)", c.Interpret.Model, mc.Provider)
	}
	if mc.BaseURL == "" {
		return fmt.Errorf("config: model %q: base_url is required", c.Interpret.Model)
	}
	if c.Interpret.Prompt == "" {
		return fmt.Errorf("config: interpret.prompt is required")
	}
	if len(c.Interpret.Schema) == 0 {
		return fmt.Errorf("config: interpret.schema is required")
	}
	for name, f := range c.Interpret.Schema {
		switch f.Type {
		case "string", "number", "boolean":
		default:
			return fmt.Errorf("config: schema field %q: unsupported type %q", name, f.Type)
		}
		if f.Type != "number" && (f.Minimum != nil || f.Maximum != nil) {
			return fmt.Errorf("config: schema field %q: minimum/maximum require type number", name)
		}
		if (f.Minimum != nil && (math.IsNaN(*f.Minimum) || math.IsInf(*f.Minimum, 0))) ||
			(f.Maximum != nil && (math.IsNaN(*f.Maximum) || math.IsInf(*f.Maximum, 0))) {
			return fmt.Errorf("config: schema field %q: minimum/maximum must be finite", name)
		}
		if f.Minimum != nil && f.Maximum != nil && *f.Minimum > *f.Maximum {
			return fmt.Errorf("config: schema field %q: minimum must not exceed maximum", name)
		}
	}
	for i, f := range c.Filter {
		if err := f.Validate(); err != nil {
			return fmt.Errorf("config: filter %d: %w", i+1, err)
		}
	}

	validateThen := func(t policy.Then, where string) error {
		// A rule that sets several outcomes is almost certainly a YAML typo
		// (a leftover ignore under a new notify). Rather than picking a
		// winner, reject it: ambiguity in outcome selection is exactly the
		// kind of thing policy must never have.
		set := 0
		for _, b := range []bool{t.Notify != nil, t.Action != nil, t.Delegate != nil, t.Ignore} {
			if b {
				set++
			}
		}
		if set > 1 {
			return fmt.Errorf("config: %s: set at most one of notify, action, delegate, ignore", where)
		}
		if t.Notify != nil && t.Notify.Via != "stdout" {
			return fmt.Errorf("config: %s: notify.via %q not supported (v0.1: stdout)", where, t.Notify.Via)
		}
		if t.Action != nil {
			switch t.Action.Type {
			case "http":
				if t.Action.URL == "" {
					return fmt.Errorf("config: %s: action.url is required for type http", where)
				}
			case "emit":
				if t.Action.EventType == "" {
					return fmt.Errorf("config: %s: action.event_type is required for type emit", where)
				}
			default:
				return fmt.Errorf("config: %s: action.type %q not supported (v0.1: http, emit)", where, t.Action.Type)
			}
		}
		if t.Delegate != nil {
			if t.Delegate.Agent == "" {
				return fmt.Errorf("config: %s: delegate.agent is required", where)
			}
			// The reference is resolved now, at validation time, so a typo'd
			// agent name fails startup instead of surfacing as a mid-flight
			// "unknown agent" execution error on some future event.
			if _, ok := c.Agents[t.Delegate.Agent]; !ok {
				return fmt.Errorf("config: %s: delegate.agent %q not defined in agents", where, t.Delegate.Agent)
			}
		}
		if set == 0 && !t.Shadow {
			return fmt.Errorf("config: %s: must set notify, action, delegate, ignore: true, or shadow: true", where)
		}
		return nil
	}
	for name, a := range c.Agents {
		if a.Endpoint == "" {
			return fmt.Errorf("config: agent %q: endpoint is required", name)
		}
	}
	seenSources := map[string]bool{}
	for i := range c.Sources {
		s := &c.Sources[i]
		if s.Name == "" {
			return fmt.Errorf("config: source %d: name is required", i+1)
		}
		// Source names become Event.Source and cursor keys: uniqueness is
		// what keeps two pollers from silently sharing dedup identity.
		if seenSources[s.Name] {
			return fmt.Errorf("config: source %q: duplicate name", s.Name)
		}
		seenSources[s.Name] = true
		if s.Type != "http-poller" {
			return fmt.Errorf("config: source %q: type %q not supported (v0.1: http-poller)", s.Name, s.Type)
		}
		if s.URL == "" {
			return fmt.Errorf("config: source %q: url is required", s.Name)
		}
		// The floor protects the polled target from a typo like `every: 1ms`
		// turning into a self-inflicted denial of service.
		if s.Every < time.Second {
			return fmt.Errorf("config: source %q: every must be at least 1s", s.Name)
		}
		if s.EventType == "" {
			return fmt.Errorf("config: source %q: event_type is required", s.Name)
		}
	}
	for i, r := range c.Policy.Rules {
		if len(r.If) == 0 {
			return fmt.Errorf("config: policy rule %d: empty if", i+1)
		}
		if err := validateThen(r.Then, fmt.Sprintf("policy rule %d", i+1)); err != nil {
			return err
		}
	}
	return validateThen(c.Policy.Default, "default")
}

// Command mrmr is the single binary for the mrmr runtime. `run` loads a YAML
// config, opens SQLite, and serves POST /api/events. Each request is
// processed synchronously: the event is persisted; duplicates short-circuit
// there with a "duplicate" marker; and the rest run deterministic filters,
// model interpretation, policy, and outcome in order, with filter-excluded
// events stopping before the model call. The HTTP response is the trace of
// everything that happened. Synchronous processing is the point: it makes
// the runtime's behavior explainable end to end and keeps the invariants
// simple (no queue, no worker goroutines, no lost requests) at the cost of
// latency, which is fine for ambient event volumes.
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/source"
	"github.com/heath0xff/mrmr/internal/storage"
)

func main() {
	log.SetFlags(log.LstdFlags | log.LUTC)

	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: mrmr <run|eval|events|label|dataset|inspect> [options]")
		os.Exit(2)
	}

	switch os.Args[1] {
	case "run":
		if err := run(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "eval":
		if err := eval(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "events":
		if err := events(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "label":
		if err := label(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "dataset":
		if err := dataset(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "inspect":
		if err := inspect(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "-h", "--help", "help":
		fmt.Println("usage: mrmr <run|eval|events|label|dataset|inspect> [options]")
	default:
		log.Fatalf("unknown subcommand %q", os.Args[1])
	}
}

// run boots the server and blocks until SIGINT/SIGTERM. Shutdown is graceful
// because an in-flight event is mid-pipeline: killing it between the event
// persist and the decision persist would leave a half-processed event with
// no way to tell from outside whether anything was lost.
func run(args []string) error {
	fs := flag.NewFlagSet("mrmr run", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	if err := fs.Parse(args); err != nil {
		return err
	}

	cfg, err := config.Load(*configPath)
	if err != nil {
		return err
	}

	db, err := storage.Open(cfg.DB.Path)
	if err != nil {
		return err
	}
	defer db.Close()

	rt := &runtime.Runtime{
		DB:       db,
		Client:   &model.Client{},
		ModelCfg: cfg.Models[cfg.Interpret.Model],
		ModelKey: cfg.Interpret.Model,
		Prompt:   cfg.Interpret.Prompt,
		Schema:   cfg.Interpret.Schema,
		Policy:   cfg.Policy,
		Filters:  cfg.Filter,
	}
	// Resolve delegation endpoints once at startup; policy rules reference
	// agents by name only.
	rt.AgentEndpoints = make(map[string]string, len(cfg.Agents))
	for name, a := range cfg.Agents {
		rt.AgentEndpoints[name] = a.Endpoint
	}

	mux := http.NewServeMux()
	mux.HandleFunc("POST /api/events", eventsHandler(rt))

	srv := &http.Server{Addr: cfg.Server.Addr, Handler: mux}

	// Cancel the context on SIGINT/SIGTERM so Shutdown has a deadline and a
	// second signal still hard-exits. Pollers share this context: shutdown
	// cancels in-flight fetches and stops the tick loops.
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	// One goroutine per source, owned by the WaitGroup, stopped by ctx.
	var sources sync.WaitGroup
	for _, sc := range cfg.Sources {
		if sc.Type != "http-poller" {
			return fmt.Errorf("source %q: unknown type %q", sc.Name, sc.Type) // config validation should prevent this
		}
		p, err := source.NewHTTPPoller(sc)
		if err != nil {
			return err
		}
		sources.Add(1)
		go func() {
			defer sources.Done()
			p.Run(ctx, rt)
		}()
	}

	errCh := make(chan error, 1)
	go func() { errCh <- srv.ListenAndServe() }()

	log.Printf("mrmr listening on %s (db: %s, model: %s, sources: %d)", cfg.Server.Addr, cfg.DB.Path, cfg.Interpret.Model, len(cfg.Sources))

	select {
	case err := <-errCh:
		return err
	case <-ctx.Done():
	}

	// Bound shutdown so a hung request can't wedge the process; the pipeline
	// itself also respects ctx via the request context.
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	// Pollers finish their current poll (Ingest is synchronous) or stop at
	// the next ctx check; a wedged fetch is bounded by the client timeout,
	// so waiting briefly is enough — a leak here would defeat shutdown.
	waitSources := make(chan struct{})
	go func() { sources.Wait(); close(waitSources) }()
	select {
	case <-waitSources:
	case <-shutdownCtx.Done():
		return fmt.Errorf("shutdown: pollers did not stop in time")
	}
	return nil
}

// eventsRequest is the wire shape for POST /api/events. Only type and source
// are required; data and metadata are opaque maps passed through to the event.
type eventsRequest struct {
	Type     string         `json:"type"`
	Source   string         `json:"source"`
	Subject  string         `json:"subject,omitempty"`
	Data     map[string]any `json:"data,omitempty"`
	Metadata map[string]any `json:"metadata,omitempty"`
}

// eventsHandler returns the POST /api/events handler. Ingest is
// synchronous: by the time the 200 goes out, the event's fate is final:
// a duplicate, a filter exclusion before any model call, or an executed
// policy outcome. Ingest errors are persistence
// failures and map to 500; everything the model does wrong is already
// captured in the decision and trace, not in the HTTP status.
func eventsHandler(rt *runtime.Runtime) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// This is the runtime's only external ingress, so bodies are bounded:
		// a normalized event is small, and one oversized POST must not be able
		// to eat memory. 1 MiB is generous headroom over any real event.
		r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
		var req eventsRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			writeError(w, http.StatusBadRequest, "malformed JSON body: "+err.Error())
			return
		}
		if req.Type == "" || req.Source == "" {
			writeError(w, http.StatusBadRequest, "both \"type\" and \"source\" are required")
			return
		}

		e := event.Event{
			ID:        event.NewID("evt_"),
			Type:      req.Type,
			Source:    req.Source,
			Subject:   req.Subject,
			Timestamp: time.Now().UTC(),
			Data:      req.Data,
			Metadata:  req.Metadata,
		}

		resp, err := rt.Ingest(r.Context(), e)
		if err != nil {
			// Persistence failed, which means the event's fate is unknown
			// to the caller; 500 (not 4xx) so clients may retry.
			log.Printf("ingest %s failed: %v", e.ID, err)
			writeError(w, http.StatusInternalServerError, "ingest failed")
			return
		}

		// One line per event so stdout doubles as a processing log. This is
		// the whole observability story for milestone 1: the response JSON
		// contains the decision and the full trace.
		b, err := json.Marshal(resp)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "encode response: "+err.Error())
			return
		}
		fmt.Println(string(b))

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		w.Write(b)
	}
}

// writeError responds with the {"error": ...} envelope. Errors never carry
// internal detail beyond what the trace already exposes.
func writeError(w http.ResponseWriter, code int, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(map[string]string{"error": msg})
}

// Package runtime is the mrmr loop: persist Event → filter → interpret →
// Decision → policy → Outcome → adapter, with a trace at every step. The
// filter stage is deterministic and may short-circuit: an excluded event
// produces no Decision and no model call.
// This package is the choreography; every stage's actual work lives in its
// own package.
// The one rule that shapes everything here: fail toward ignore. A model
// outage or a garbage result degrades mrmr into a no-op — the safe direction
// — and never into an action nobody authorized.
package runtime

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"strings"
	"text/template"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/filter"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
	"github.com/heath0xff/mrmr/internal/storage"
)

// Runtime is the assembled pipeline. It is immutable after construction:
// the config that built it is the config it runs, which is what lets
// in-flight events finish under the rules they started with.
type Runtime struct {
	DB       *storage.DB
	Client   *model.Client
	ModelCfg model.Config
	ModelKey string // name in config, recorded on decisions
	Prompt   string
	Schema   model.Schema
	Policy   policy.Policy
	Filters  filter.List
	// AgentEndpoints maps a policy delegate.agent name to its HTTP endpoint.
	// Resolved at startup from config so policy rules never carry URLs.
	AgentEndpoints map[string]string
	// HTTP is the client for action/delegate side effects. Nil means a
	// default 10s timeout — outbound effects must be bounded, never hang
	// the synchronous ingest path.
	HTTP *http.Client
}

// maxDepth caps emit-event recursion: a causal chain longer than this is a
// loop, and loops get recorded and ignored, not executed.
const maxDepth = 10

// TraceStep is one observable moment in an event's journey. It is an alias,
// not a distinct type: the trace is persisted next to the event it explains,
// so the shape belongs to the domain package that storage also speaks, and
// the runtime is merely where the steps are produced.
type TraceStep = event.TraceStep

// Response is what the caller (HTTP handler) receives: the event id, the
// decision (if any), the outcome, and the full trace. It doubles as the
// stdout log line for milestone 1.
type Response struct {
	EventID   string          `json:"event_id"`
	Duplicate bool            `json:"duplicate,omitempty"`
	Decision  *event.Decision `json:"decision,omitempty"`
	Outcome   string          `json:"outcome,omitempty"`
	Trace     []TraceStep     `json:"trace"`
}

func step(t *[]TraceStep, stage, msg string) {
	*t = append(*t, TraceStep{At: time.Now().UTC(), Stage: stage, Msg: msg})
}

// Ingest is the whole pipeline for one event, synchronously. It never
// returns an error for a "bad" decision or outcome — a schema-invalid model
// or a down endpoint is normal operation, recorded in the decision and trace
// — only for persistence failures, which are the caller's (HTTP handler's)
// — only for persistence failures on writes that happen before any outcome
// is decided (the event row, the decision row). Once the outcome is chosen,
// the fate is known: later failures (execution row, trace) are logged, not
// propagated, because a 500 would claim "fate unknown" about a decided
// outcome and a source's retry would dedup-drop into nothing.
func (r *Runtime) Ingest(ctx context.Context, e event.Event) (*Response, error) {
	t := &[]TraceStep{}
	resp, err := r.ingest(ctx, e, t)
	if err != nil {
		return nil, err
	}
	// The trace is persisted once, here, rather than at each of ingest's
	// exits — one write, and every path is covered by construction.
	//
	// A duplicate is the exception: it never inserted an events row under
	// this id, so the trace's foreign key would have nothing to point at,
	// and there is nothing to inspect anyway — the original event's trace
	// already tells that story. A trace write failure is logged and the
	// response returned normally: the event, decision, and execution rows
	// are all durable and the outcome has fired, so the request succeeded
	// — only the durable copy of the trace is lost, and the in-memory
	// trace still goes out with the response.
	if !resp.Duplicate {
		if serr := r.DB.InsertTrace(e.ID, *t); serr != nil {
			log.Printf("mrmr: persist trace for %s failed (trace only in response): %v", e.ID, serr)
		}
	}
	return resp, nil
}

// ingest runs the pipeline and appends to the trace as it goes. It is
// separate from Ingest so that trace persistence has exactly one call site.
func (r *Runtime) ingest(ctx context.Context, e event.Event, t *[]TraceStep) (*Response, error) {
	step(t, "receive", fmt.Sprintf("type=%s source=%s", e.Type, e.Source))

	rec, err := r.DB.InsertEvent(e)
	if err != nil {
		return nil, fmt.Errorf("persist event: %w", err)
	}
	if rec.Duplicate {
		step(t, "duplicate", "dropped: (source, dedup_key) already seen")
		return &Response{EventID: e.ID, Duplicate: true, Trace: *t}, nil
	}
	step(t, "persist", "event stored")

	// Recursion guard for mrmr-emitted events. The event is durable and
	// traceable, but past the depth cap it is forced to ignore: a flow pair
	// emitting into each other must surface as ignore rows here, not as an
	// infinite model-calling loop.
	if e.Depth > maxDepth {
		step(t, "depth", fmt.Sprintf("causal depth %d exceeds max %d; recorded but forced to ignore", e.Depth, maxDepth))
		r.recordExecution(e.ID, "", "ignore", "", "ok", "max causal depth exceeded")
		step(t, "outcome", "executed ignore")
		return &Response{EventID: e.ID, Outcome: "ignore", Trace: *t}, nil
	}

	// Filters run after the event is durable and before any model
	// call: they are the cost gate. An excluded event produces no
	// Decision (the model never ran, and a Decision records model
	// judgment) but does produce an Execution row: the audit trail
	// must show where the event stopped. The adapter is empty because
	// a filter is a gate, not an Adapter under the project's domain
	// boundary; the filter trace stage names the stop point.
	if len(r.Filters) > 0 {
		passed, reason := r.Filters.Evaluate(e)
		if !passed {
			step(t, "filter", "excluded: "+reason)
			r.recordExecution(e.ID, "", "ignore", "", "filtered", "")
			step(t, "outcome", "executed ignore")
			return &Response{EventID: e.ID, Outcome: "ignore", Trace: *t}, nil
		}
		step(t, "filter", fmt.Sprintf("%d checks passed", len(r.Filters)))
	}

	dec := &event.Decision{ID: event.NewID("dec_"), EventID: e.ID, Interpreter: r.ModelKey, Model: r.ModelCfg.Model}

	eventJSON, _ := json.Marshal(e)
	result, latency, modelID, err := r.Client.Interpret(ctx, r.ModelCfg, r.ModelKey, r.Prompt, r.Schema, eventJSON)
	dec.Model = modelID
	dec.LatencyMs = latency

	if err != nil {
		if inv, ok := err.(*model.InvalidOutputError); ok {
			dec.Status = "invalid"
			dec.Error = inv.Error()
			step(t, "interpret", "schema-invalid after retry")
		} else {
			dec.Status = "errored"
			dec.Error = err.Error()
			step(t, "interpret", "model error: "+err.Error())
		}
	} else {
		dec.Status = "ok"
		dec.Result = result
		if b, jerr := json.Marshal(result); jerr == nil {
			step(t, "interpret", fmt.Sprintf("model=%s latency_ms=%d result=%s", modelID, latency, b))
		}
	}
	if serr := r.DB.InsertDecision(*dec); serr != nil {
		return nil, fmt.Errorf("persist decision: %w", serr)
	}

	// Fail toward ignore: invalid or errored decisions never reach policy.
	// A model that is down or wrong must not be able to trigger actions —
	// policy evaluates judgment, and there is no judgment to evaluate.
	var then policy.Then
	if dec.Status == "ok" {
		var ruleIdx int
		then, ruleIdx = r.Policy.Evaluate(dec.Result) // assignment, not := — the outer then must be set here
		if ruleIdx < 0 {
			step(t, "policy", "default → "+then.Outcome())
		} else {
			step(t, "policy", fmt.Sprintf("rule %d → %s", ruleIdx+1, then.Outcome()))
		}
	} else {
		then = policy.Then{Ignore: true}
		step(t, "policy", "routed to ignore ("+dec.Status+" decision)")
	}

	// Shadow records the outcome as if it had fired but executes nothing —
	// how a new flow earns trust before going live. Promotion is later a
	// config change, not a rewrite.
	execErr := ""
	if then.Shadow {
		step(t, "outcome", "shadow: "+then.Outcome()+" recorded but not executed")
	} else {
		execErr = r.execute(ctx, then, dec, e, t)
	}
	if execErr != "" {
		step(t, "outcome", "error: "+execErr)
	} else if !then.Shadow {
		step(t, "outcome", "executed "+then.Outcome())
	}
	status := "ok"
	switch {
	case execErr != "":
		status = "error"
	case then.Shadow:
		status = "shadow"
	}
	// This is the one execution write on a path where a side effect may
	// have already fired, so it must never fail the request: the outcome
	// is decided and the response still reports it. The audit gap (no
	// execution row) is real but a 500 would not repair it — the source's
	// retry would dedup-drop, losing the row permanently.
	r.recordExecution(e.ID, dec.ID, then.Outcome(), adapterFor(then), status, execErr)

	return &Response{EventID: e.ID, Decision: dec, Outcome: then.Outcome(), Trace: *t}, nil
}

// recordExecution persists an execution row, degrading to a log entry on
// failure. Every caller sits after the event row is durable and the outcome
// is decided, so a write failure must not fail the request — a 500 would
// claim "fate unknown" about a decided outcome and the source's retry would
// dedup-drop, losing the row permanently anyway.
func (r *Runtime) recordExecution(eventID, decisionID, outcome, adapter, status, execErr string) {
	if serr := r.DB.InsertExecution(event.NewID("exe_"), eventID, decisionID, outcome, adapter, status, execErr); serr != nil {
		log.Printf("mrmr: persist execution for %s failed: %v", eventID, serr)
	}
}

func adapterFor(t policy.Then) string {
	switch {
	case t.Notify != nil:
		return t.Notify.Via
	case t.Action != nil:
		return t.Action.Type
	case t.Delegate != nil:
		return t.Delegate.Agent
	}
	return ""
}

// execute performs the outcome's side effect and returns "" on success.
// Ignore is a success — most events should end here; suppressing noise is
// half the point of ambient AI. Emit recursion is synchronous by design:
// it is depth-capped, so no goroutines, no queue, nothing to leak.
func (r *Runtime) execute(ctx context.Context, t policy.Then, dec *event.Decision, parent event.Event, tr *[]TraceStep) string {
	switch {
	case t.Notify != nil:
		if t.Notify.Via != "stdout" {
			return fmt.Sprintf("unsupported notify via %q", t.Notify.Via) // config validation should prevent this
		}
		fmt.Println(renderMessage(t.Notify.Message, dec))
		return ""

	case t.Action != nil:
		switch t.Action.Type {
		case "http":
			method := t.Action.Method
			if method == "" {
				method = http.MethodPost
			}
			// Body template over the decision; empty body is the full result
			// JSON, same default as notify, so a bare action is still useful.
			return r.do(ctx, method, t.Action.URL, renderMessage(t.Action.Body, dec))
		case "emit":
			// The decision result becomes the child's data — the child flow's
			// interpreter judges meaning, it does not re-parse the parent's
			// decision row. ponytail: (source, source_event_id) = (mrmr,
			// parent id) means one emit per parent; multiple emit rules on one
			// flow would dedup-collide. Split flows if that's ever needed.
			child := event.Event{
				ID:        event.NewID("evt_"),
				Type:      t.Action.EventType,
				Source:    "mrmr",
				Timestamp: time.Now().UTC(),
				Data:      dec.Result,
				Metadata:  map[string]any{"source_event_id": parent.ID},
				Depth:     parent.Depth + 1,
			}
			step(tr, "emit", "emitted "+child.ID+" type="+child.Type+" depth="+fmt.Sprint(child.Depth))
			resp, err := r.Ingest(ctx, child)
			if err != nil {
				return fmt.Sprintf("emit: %v", err)
			}
			step(tr, "emit", "child outcome "+resp.Outcome)
			return ""
		}
		return fmt.Sprintf("unsupported action type %q", t.Action.Type) // config validation should prevent this

	case t.Delegate != nil:
		endpoint, ok := r.AgentEndpoints[t.Delegate.Agent]
		if !ok {
			return fmt.Sprintf("unknown agent %q", t.Delegate.Agent) // config validation should prevent this
		}
		// Generic HTTP agent contract: one POST, JSON payload, 2xx means
		// accepted. The agent's work is its own business; mrmr records that
		// it delegated, to whom, and why.
		payload, _ := json.Marshal(struct {
			EventID  string         `json:"event_id"`
			Decision map[string]any `json:"decision"`
			Prompt   string         `json:"prompt"`
		}{dec.EventID, dec.Result, t.Delegate.Prompt})
		return r.do(ctx, http.MethodPost, endpoint, string(payload))
	}
	return "" // ignore is a success
}

// do sends one bounded HTTP side effect and returns "" on a 2xx. The body
// is drained (bounded) so the connection is reusable; response content is
// not interpreted — actions are fire-and-record, not request/response.
func (r *Runtime) do(ctx context.Context, method, url, body string) string {
	req, err := http.NewRequestWithContext(ctx, method, url, strings.NewReader(body))
	if err != nil {
		return fmt.Sprintf("build request: %v", err)
	}
	if body != "" {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := r.httpClient().Do(req)
	if err != nil {
		return fmt.Sprintf("http %s %s: %v", method, url, err)
	}
	defer resp.Body.Close()
	io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<16))
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return fmt.Sprintf("http %s %s: status %d", method, url, resp.StatusCode)
	}
	return ""
}

func (r *Runtime) httpClient() *http.Client {
	if r.HTTP != nil {
		return r.HTTP
	}
	return &http.Client{Timeout: 10 * time.Second}
}

// renderMessage applies the notify template over the decision result.
// An empty template renders the full result JSON so a bare `notify: {via: x}`
// is still useful. Template errors degrade to a bracketed note rather than
// dropping the notification — a notification with a hint of what went wrong
// beats silence.
func renderMessage(tmpl string, dec *event.Decision) string {
	if tmpl == "" {
		b, _ := json.Marshal(dec.Result)
		return fmt.Sprintf("[%s] %s", dec.EventID, b)
	}
	t, err := template.New("notify").Parse(tmpl)
	if err != nil {
		return fmt.Sprintf("[%s] (bad notify template: %v)", dec.EventID, err)
	}
	var sb strings.Builder
	if err := t.Execute(&sb, map[string]any{"result": dec.Result, "event": map[string]any{"id": dec.EventID}}); err != nil {
		return fmt.Sprintf("[%s] (template error: %v)", dec.EventID, err)
	}
	return sb.String()
}

// Source cursor persistence. The cursor is a per-source watermark: the
// poller's restart-safe position in a feed. It is an optimization and a
// resume point, never the dedup mechanism — dedup lives in InsertEvent's
// (source, source_event_id) key, so a lost or stale cursor can cause
// re-offering, never re-processing.
package storage

import (
	"database/sql"
	"fmt"
)

// Cursor returns the persisted watermark for a source. An unknown source is
// a fresh poller: "" and no error.
func (d *DB) Cursor(name string) (string, error) {
	var c string
	err := d.QueryRow(`SELECT cursor FROM source_cursors WHERE name = ?`, name).Scan(&c)
	if err == sql.ErrNoRows {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("read cursor %s: %w", name, err)
	}
	return c, nil
}

// SetCursor persists the watermark upsert-style: the poll loop is the only
// writer per source, so last-write-wins is correct.
func (d *DB) SetCursor(name, cursor string) error {
	_, err := d.Exec(`INSERT INTO source_cursors (name, cursor, updated_at) VALUES (?, ?, ?)
		ON CONFLICT(name) DO UPDATE SET cursor = excluded.cursor, updated_at = excluded.updated_at`,
		name, cursor, now())
	if err != nil {
		return fmt.Errorf("set cursor %s: %w", name, err)
	}
	return nil
}

// Package model talks to OpenAI-compatible chat completion endpoints and
// returns schema-validated structured results. Everything here treats the
// model as an untrusted producer of JSON: output is parsed defensively,
// validated against the configured schema, and retried exactly once with the
// validation error appended so small local models can self-correct. The
// caller (the runtime) decides what a bad result means — this package only
// reports it.
package model

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"
)

// Config describes one model endpoint. Secrets are referenced by env var
// name only (api_key_env) — never inlined — so config files stay safe to
// commit and inspect.
type Config struct {
	Provider  string `yaml:"provider"` // openai-compatible (only one for now)
	BaseURL   string `yaml:"base_url"`
	APIKeyEnv string `yaml:"api_key_env"`
	Model     string `yaml:"model"`
}

// Field is the v0 schema subset: flat typed fields with optional enums and numeric bounds.
type Field struct {
	Type    string   `yaml:"type"` // string | number | boolean
	Enum    []any    `yaml:"enum"`
	Minimum *float64 `yaml:"minimum"`
	Maximum *float64 `yaml:"maximum"`
}

type Schema map[string]Field

type Client struct{}

const (
	maxAttempts    = 3 // total HTTP calls per interpretation, all failure modes combined
	requestTimeout = 60 * time.Second
	retryBackoff   = 250 * time.Millisecond // only between transport attempts; a briefly overloaded local model needs a moment
)

type InvalidOutputError struct{ Detail string }

func (e *InvalidOutputError) Error() string { return "invalid model output: " + e.Detail }

// Interpret sends the event to the configured model and returns the
// validated result map. Error is *InvalidOutputError when the output failed
// schema validation after its one self-correction retry; other errors are
// transport/endpoint failures. The distinction matters to the caller: invalid
// output is the model's fault and is recorded on the decision; transport
// failure is an endpoint outage and must not be retried indefinitely by anyone.
//
// Two bounds apply together on a single call budget of maxAttempts: a
// schema-invalid output is retried exactly once with the validation error
// appended (IMPLEMENTATION.md pins this), and transport failures (network
// errors, 5xx) consume the remaining budget rather than aborting mid-loop,
// so one blip during self-correction doesn't fail an event that had calls
// left. Non-retryable client errors (401 wrong key, 404 wrong model) return
// immediately — retrying those is pure noise. Latency sums every call: the
// trace cares how long interpretation took in total, corrections included.
func (c *Client) Interpret(ctx context.Context, cfg Config, interpreter string, prompt string, schema Schema, eventJSON []byte) (result map[string]any, latencyMs int64, model string, err error) {
	model = cfg.Model
	sys := prompt + "\n\nRespond with a single JSON object with exactly these fields:\n" + schemaJSON(schema)
	messages := []message{{"system", sys}, {"user", string(eventJSON)}}

	var (
		transportErr  error
		invalidDetail string
		usedRetry     bool // one self-correction attempt, ever
	)
	for calls := 0; calls < maxAttempts; {
		if calls > 0 {
			select {
			case <-ctx.Done():
				return nil, latencyMs, model, ctx.Err()
			case <-time.After(retryBackoff):
			}
		}
		content, lat, err := c.complete(ctx, cfg, schema, messages)
		calls++
		latencyMs += lat
		if err != nil {
			transportErr = fmt.Errorf("model call (attempt %d): %w", calls, err)
			var se *statusError
			if errors.As(err, &se) && se.Code < 500 {
				// 4xx won't get better by retrying. (A response_format 400 was
				// already handled and exhausted inside complete.)
				return nil, latencyMs, model, transportErr
			}
			continue // network error or 5xx: retry within the remaining budget
		}
		transportErr = nil
		res, verr := parseAndValidate(content, schema)
		if verr == nil {
			return res, latencyMs, model, nil
		}
		invalidDetail = verr.Error()
		if usedRetry {
			return nil, latencyMs, model, &InvalidOutputError{Detail: invalidDetail}
		}
		// One self-correction hop: show the model its failed output and the
		// validation error so small local models can fix themselves. This
		// path is expected to be routine and must stay bounded.
		usedRetry = true
		messages = append(messages,
			message{"assistant", content},
			message{"user", "Your previous output failed validation: " + verr.Error() + "\nRespond again with a JSON object matching the schema exactly."},
		)
	}
	if transportErr != nil {
		return nil, latencyMs, model, transportErr
	}
	return nil, latencyMs, model, &InvalidOutputError{Detail: invalidDetail}
}

type message struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

type responseFormat struct {
	Type       string         `json:"type"`
	JSONSchema *jsonSchemaFmt `json:"json_schema,omitempty"`
}

type jsonSchemaFmt struct {
	Name   string         `json:"name"`
	Strict bool           `json:"strict"`
	Schema map[string]any `json:"schema"`
}

type chatRequest struct {
	Model          string          `json:"model"`
	Messages       []message       `json:"messages"`
	Temperature    float64         `json:"temperature"`
	ResponseFormat *responseFormat `json:"response_format,omitempty"`
}

type chatResponse struct {
	Choices []struct {
		Message struct {
			Content string `json:"content"`
		} `json:"message"`
	} `json:"choices"`
}

// statusError distinguishes endpoint HTTP failures from transport failures.
// The distinction is load-bearing: a 400 to a schema-constrained request
// means the endpoint doesn't support response_format and is worth retrying
// without it, while a 500 is an outage that only counts against the retry
// budget.
type statusError struct {
	Code int
	Body string
}

func (e *statusError) Error() string {
	return fmt.Sprintf("endpoint returned %d: %s", e.Code, e.Body)
}

// complete performs one chat completion. It first asks for schema-constrained
// decoding; endpoints that reject response_format (HTTP 400) are retried once
// without it, falling back to validation alone. This keeps the client
// compatible with llama.cpp/vLLM/Ollama endpoints that support grammar
// constraints as well as plain ones that don't.
func (c *Client) complete(ctx context.Context, cfg Config, schema Schema, messages []message) (content string, latencyMs int64, err error) {
	hc := &http.Client{Timeout: requestTimeout}
	req := chatRequest{
		Model:          cfg.Model,
		Messages:       messages,
		Temperature:    0,
		ResponseFormat: &responseFormat{Type: "json_schema", JSONSchema: &jsonSchemaFmt{Name: "decision", Strict: true, Schema: schemaMap(schema)}},
	}
	for i := 0; i < 2; i++ { // 0: with response_format, 1: without (endpoint lacks schema support)
		start := time.Now()
		content, err = c.post(ctx, hc, cfg, req)
		latencyMs += time.Since(start).Milliseconds()
		var se *statusError
		if err == nil || !(errors.As(err, &se) && se.Code == http.StatusBadRequest) {
			return content, latencyMs, err
		}
		req.ResponseFormat = nil
	}
	return
}

func (c *Client) post(ctx context.Context, hc *http.Client, cfg Config, req chatRequest) (string, error) {
	body, _ := json.Marshal(req)
	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, strings.TrimRight(cfg.BaseURL, "/")+"/chat/completions", bytes.NewReader(body))
	if err != nil {
		return "", err
	}
	httpReq.Header.Set("Content-Type", "application/json")
	if cfg.APIKeyEnv != "" {
		if key := os.Getenv(cfg.APIKeyEnv); key != "" {
			httpReq.Header.Set("Authorization", "Bearer "+key)
		}
	}
	resp, err := hc.Do(httpReq)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		// Cap the body we read: endpoint error pages can be arbitrarily large
		// and only the first line or two is ever useful in a trace.
		b, _ := io.ReadAll(io.LimitReader(resp.Body, 2048))
		return "", &statusError{Code: resp.StatusCode, Body: strings.TrimSpace(string(b))}
	}
	var cr chatResponse
	if err := json.NewDecoder(resp.Body).Decode(&cr); err != nil {
		return "", fmt.Errorf("decode response: %w", err)
	}
	if len(cr.Choices) == 0 {
		return "", fmt.Errorf("empty choices in response")
	}
	return cr.Choices[0].Message.Content, nil
}

// schemaJSON renders the schema as the instruction block for the prompt.
func schemaJSON(s Schema) string {
	b, _ := json.MarshalIndent(schemaMap(s), "", "  ")
	return string(b)
}

// schemaMap converts the flat Schema into a JSON-Schema object map for
// constrained decoding (llama.cpp grammars / vLLM guided JSON / etc.).
func schemaMap(s Schema) map[string]any {
	props := map[string]any{}
	required := []string{}
	for name, f := range s {
		p := map[string]any{"type": f.Type}
		if len(f.Enum) > 0 {
			p["enum"] = f.Enum
		}
		if f.Minimum != nil {
			p["minimum"] = *f.Minimum
		}
		if f.Maximum != nil {
			p["maximum"] = *f.Maximum
		}
		props[name] = p
		required = append(required, name)
	}
	return map[string]any{
		"type":                 "object",
		"properties":           props,
		"required":             required,
		"additionalProperties": false,
	}
}

// parseAndValidate extracts a JSON object from model output. Small local
// models routinely wrap JSON in markdown fences or lead with prose even when
// told not to, so we scan for the outermost braces instead of trusting the
// whole string to be JSON. If the braces contain garbage, Unmarshal catches it.
func parseAndValidate(content string, schema Schema) (map[string]any, error) {
	// Tolerate models that wrap JSON in fences or prose.
	start := strings.Index(content, "{")
	end := strings.LastIndex(content, "}")
	if start < 0 || end <= start {
		return nil, fmt.Errorf("no JSON object found in output")
	}
	var res map[string]any
	if err := json.Unmarshal([]byte(content[start:end+1]), &res); err != nil {
		return nil, fmt.Errorf("unparseable JSON: %v", err)
	}
	return res, validate(res, schema)
}

// validate checks a parsed result against the flat schema. It enforces
// exact shape — every field present, correct type, enum membership, no
// extras — because downstream policy conditions are silent when a field is
// missing, and a silently-missing field is indistinguishable from a
// deliberate route to the default outcome.
func validate(res map[string]any, schema Schema) error {
	for name, f := range schema {
		v, ok := res[name]
		if !ok {
			return fmt.Errorf("missing field %q", name)
		}
		switch f.Type {
		case "string":
			if _, ok := v.(string); !ok {
				return fmt.Errorf("field %q: want string", name)
			}
		case "number":
			n, ok := v.(float64)
			if !ok {
				return fmt.Errorf("field %q: want number", name)
			}
			if f.Minimum != nil && n < *f.Minimum {
				return fmt.Errorf("field %q: value %v below minimum %v", name, n, *f.Minimum)
			}
			if f.Maximum != nil && n > *f.Maximum {
				return fmt.Errorf("field %q: value %v above maximum %v", name, n, *f.Maximum)
			}
		case "boolean":
			if _, ok := v.(bool); !ok {
				return fmt.Errorf("field %q: want boolean", name)
			}
		default:
			return fmt.Errorf("schema field %q: unsupported type %q", name, f.Type)
		}
		if len(f.Enum) > 0 {
			found := false
			for _, e := range f.Enum {
				if fmt.Sprint(e) == fmt.Sprint(v) {
					found = true
					break
				}
			}
			if !found {
				return fmt.Errorf("field %q: value %v not in enum", name, v)
			}
		}
	}
	for name := range res {
		if _, ok := schema[name]; !ok {
			return fmt.Errorf("unexpected field %q", name)
		}
	}
	return nil
}

// Package policy evaluates deterministic first-match-wins rules against a
// decision result. This is where mrmr's core invariant lives: the model
// recommends, the runtime decides. Everything here is pure evaluation —
// no I/O, no time, no randomness — so a given (rules, result) pair always
// produces the same outcome, which is what makes policy inspectable and
// trustworthy. Condition semantics are deliberately minimal (ANDed
// conditions, literal equality or a handful of operators, first match wins,
// no OR or nesting); anything richer is a later addition, not a v0 gap.
package policy

import (
	"fmt"
	"strconv"
	"strings"
)

// Notify describes a notification outcome. Via names the adapter; v0.1
// ships only stdout. Message is a Go template executed over the decision
// result so flows can surface the model's own summary.
type Notify struct {
	Via     string `yaml:"via"`
	Message string `yaml:"message"` // Go template over {result: ...}; empty = summary default
}

// Action is a bounded deterministic action. Type http sends an HTTP request
// (Method defaults to POST; Body is a Go template over the decision, default
// the full result JSON). Type emit re-ingests a new Event into the runtime
// (EventType names it; the decision result becomes its data) — the recursion
// guard lives in the runtime, not here.
type Action struct {
	Type      string `yaml:"type"`
	Method    string `yaml:"method"`
	URL       string `yaml:"url"`
	Body      string `yaml:"body"`
	EventType string `yaml:"event_type"` // emit only
}

// Delegate hands the event to a more capable agent via a generic HTTP
// endpoint. Agent names an entry in the config's `agents:` map; the runtime
// resolves it to an endpoint, so policy never carries URLs.
type Delegate struct {
	Agent  string `yaml:"agent"`
	Prompt string `yaml:"prompt"`
}

// Then is the selected outcome for an event. At most one of Notify, Action,
// Delegate, Ignore is set; config validation enforces that, and the runtime
// trusts it. Shadow is an orthogonal modifier: the outcome is decided and
// recorded exactly as it would fire, but no side effect leaves the runtime —
// that is how a new flow earns trust before going live. Shadow alone (no
// outcome) means ignore.
type Then struct {
	Notify   *Notify   `yaml:"notify"`
	Action   *Action   `yaml:"action"`
	Delegate *Delegate `yaml:"delegate"`
	Ignore   bool      `yaml:"ignore"`
	Shadow   bool      `yaml:"shadow"`
}

func (t Then) Outcome() string {
	switch {
	case t.Action != nil:
		return "act"
	case t.Delegate != nil:
		return "delegate"
	case t.Notify != nil:
		return "notify"
	default:
		return "ignore"
	}
}

// Rule is one policy line: ANDed conditions and the outcome they select.
type Rule struct {
	If   map[string]any `yaml:"if"` // ANDed; value is literal or operator string
	Then Then           `yaml:"then"`
}

// Policy is the ordered rule list plus the fall-through default. Order is
// significant: rules evaluate top to bottom and the first match wins, so a
// policy file reads like the author's priority order.
type Policy struct {
	Rules   []Rule `yaml:"policy"`
	Default Then   `yaml:"default"`
}

// Evaluate returns the outcome of the first rule whose conditions all match,
// or the default. The second return value is the matched rule's index into
// Rules (0-based), or -1 when the default applied — the trace needs to say
// *which* rule fired, not just what it did, or "why did this happen?" is
// half-answered. A condition naming a field the result doesn't have simply
// doesn't match — missing data must fall through to less aggressive
// outcomes, never block them.
func (p Policy) Evaluate(result map[string]any) (Then, int) {
	for i, r := range p.Rules {
		if matchesAll(r.If, result) {
			return r.Then, i
		}
	}
	return p.Default, -1
}

func matchesAll(conds map[string]any, result map[string]any) bool {
	for key, want := range conds {
		path := strings.TrimPrefix(key, "result.")
		got, ok := result[path]
		if !ok {
			return false
		}
		if !match(want, got) {
			return false
		}
	}
	return true
}

// match compares a condition value against the actual result value. A
// string condition is either an operator expression ("> 0.8") or a literal
// for equality; anything else (numbers, booleans) is a literal. Comparison
// is by fmt.Sprint so YAML scalars and JSON values line up without a
// type-coercion matrix.
func match(want any, got any) bool {
	if w, ok := want.(string); ok {
		if op, operand, isOp := parseOperator(w); isOp {
			return compareOp(op, operand, got)
		}
	}
	return fmt.Sprint(want) == fmt.Sprint(got)
}

var ops = []string{">=", "<=", "!=", ">", "<"}

// parseOperator recognizes "> x", ">= x", "< x", "<= x", "!= x".
func parseOperator(s string) (op, operand string, ok bool) {
	s = strings.TrimSpace(s)
	for _, o := range ops {
		if strings.HasPrefix(s, o) {
			return o, strings.TrimSpace(s[len(o):]), true
		}
	}
	return "", "", false
}

// compareOp applies an operator. Numeric comparison requires both sides to
// parse as numbers; ordering operators on non-numbers are false rather than
// an error, which keeps evaluation pure and total. "!" is the one operator
// that also makes sense for strings.
func compareOp(op, operand string, got any) bool {
	g, err1 := strconv.ParseFloat(fmt.Sprint(got), 64)
	w, err2 := strconv.ParseFloat(operand, 64)
	numeric := err1 == nil && err2 == nil
	switch op {
	case "!=":
		if numeric {
			return g != w
		}
		return fmt.Sprint(got) != operand
	case ">":
		return numeric && g > w
	case ">=":
		return numeric && g >= w
	case "<":
		return numeric && g < w
	case "<=":
		return numeric && g <= w
	}
	return false
}

// Package storage is mrmr's durable state: SQLite. This is deliberately
// the only package that knows a database exists. Migrations are explicit,
// additive, and applied in a transaction each — never silently destructive,
// because a runtime whose decisions can't be audited is a runtime whose
// decisions can't be trusted.
package storage

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"time"

	_ "modernc.org/sqlite"

	"github.com/heath0xff/mrmr/internal/event"
)

// DB wraps the SQLite handle. A single connection is used because SQLite
// is serialized anyway; the events table doubles as the queue in later
// milestones, so writes funnel through one point.
type DB struct{ *sql.DB }

type EventRecord struct {
	Event     event.Event
	Duplicate bool
}

type EventLabel struct {
	EventID         string    `json:"event_id"`
	Category        string    `json:"category"`
	RequiresAction  bool      `json:"requires_action"`
	ExpectedOutcome string    `json:"expected_outcome"`
	LabeledAt       time.Time `json:"labeled_at"`
}

type ReviewEvent struct {
	Event    event.Event     `json:"event"`
	Decision *event.Decision `json:"decision,omitempty"`
	Outcome  string          `json:"outcome,omitempty"`
	Label    *EventLabel     `json:"label,omitempty"`
}

type LabeledEvent struct {
	Event event.Event `json:"event"`
	Label EventLabel  `json:"label"`
}

// Execution is one recorded outcome attempt for an event: what the runtime
// decided to do, which adapter did it, and how that ended. DecisionID is
// empty for outcomes reached without model judgment — a filter exclusion or
// a depth-capped emit — which is itself the answer to "why was there no
// decision here?".
type Execution struct {
	ID         string    `json:"id"`
	EventID    string    `json:"event_id"`
	DecisionID string    `json:"decision_id,omitempty"`
	Outcome    string    `json:"outcome"`
	Adapter    string    `json:"adapter,omitempty"`
	Status     string    `json:"status"`
	Error      string    `json:"error,omitempty"`
	CreatedAt  time.Time `json:"created_at"`
}

// Inspection is everything the runtime durably knows about one event, which
// is the whole point of `mrmr inspect`: an outcome nobody can explain after
// the fact is an outcome nobody can trust. Decisions and Executions are
// slices rather than single values because the schema permits more than one
// of each per event; the current pipeline writes one, and reporting what is
// actually stored beats encoding that assumption in the reader.
type Inspection struct {
	Event      event.Event       `json:"event"`
	Decisions  []event.Decision  `json:"decisions,omitempty"`
	Executions []Execution       `json:"executions,omitempty"`
	Trace      []event.TraceStep `json:"trace,omitempty"`
	Label      *EventLabel       `json:"label,omitempty"`
}

// Open opens (creating if needed) the SQLite database with WAL mode
// and applies pending migrations.
func Open(path string) (*DB, error) {
	dsn := path + "?_pragma=journal_mode(WAL)&_pragma=busy_timeout(5000)&_pragma=foreign_keys(1)"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite %s: %w", path, err)
	}
	db.SetMaxOpenConns(1) // ponytail: single writer; SQLite is serialized anyway. Callers must not hold an open rows iterator across another DB call — it will deadlock on this one connection.
	d := &DB{db}
	if err := d.migrate(); err != nil {
		db.Close()
		return nil, err
	}
	return d, nil
}

// migrations run in order; each is a forward-only transaction. Add new
// ones by appending — never edit an applied migration, since existing
// deployments have already recorded its version.
var migrations = []string{`
CREATE TABLE events (
	id         TEXT PRIMARY KEY,
	type       TEXT NOT NULL,
	source     TEXT NOT NULL,
	subject    TEXT NOT NULL DEFAULT '',
	event_time TEXT NOT NULL,
	ingest_time TEXT NOT NULL,
	data       TEXT,
	metadata   TEXT,
	dedup_key  TEXT NOT NULL,
	UNIQUE(source, dedup_key)
);
CREATE INDEX idx_events_time ON events(event_time);
`,
	`
CREATE TABLE decisions (
	id          TEXT PRIMARY KEY,
	event_id    TEXT NOT NULL REFERENCES events(id),
	interpreter TEXT NOT NULL,
	model       TEXT NOT NULL,
	status      TEXT NOT NULL,
	result      TEXT,
	latency_ms  INTEGER NOT NULL,
	error       TEXT,
	created_at  TEXT NOT NULL
);
CREATE INDEX idx_decisions_event ON decisions(event_id);
`,
	`
CREATE TABLE executions (
	id          TEXT PRIMARY KEY,
	event_id    TEXT NOT NULL REFERENCES events(id),
	decision_id TEXT REFERENCES decisions(id),
	outcome     TEXT NOT NULL,
	adapter     TEXT,
	status      TEXT NOT NULL,
	error       TEXT,
	created_at  TEXT NOT NULL
);
CREATE INDEX idx_executions_event ON executions(event_id);
`,
	`
CREATE TABLE event_labels (
	event_id          TEXT PRIMARY KEY REFERENCES events(id),
	category          TEXT NOT NULL,
	requires_action   INTEGER NOT NULL CHECK (requires_action IN (0, 1)),
	expected_outcome  TEXT NOT NULL,
	labeled_at        TEXT NOT NULL
);
CREATE INDEX idx_event_labels_time ON event_labels(labeled_at);
`,
	`
CREATE TABLE event_traces (
	event_id TEXT NOT NULL REFERENCES events(id),
	seq      INTEGER NOT NULL,
	at       TEXT NOT NULL,
	stage    TEXT NOT NULL,
	msg      TEXT NOT NULL DEFAULT '',
	PRIMARY KEY (event_id, seq)
);
`,
	`
CREATE TABLE source_cursors (
	name       TEXT PRIMARY KEY,
	cursor     TEXT NOT NULL,
	updated_at TEXT NOT NULL
);
`,
}

func (d *DB) migrate() error {
	if _, err := d.Exec(`CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL)`); err != nil {
		return fmt.Errorf("create schema_migrations: %w", err)
	}
	var cur int
	if err := d.QueryRow(`SELECT COALESCE(MAX(version), 0) FROM schema_migrations`).Scan(&cur); err != nil {
		return fmt.Errorf("read schema version: %w", err)
	}
	for i, m := range migrations[cur:] {
		v := cur + i + 1
		tx, err := d.Begin()
		if err != nil {
			return err
		}
		if _, err := tx.Exec(m); err != nil {
			tx.Rollback()
			return fmt.Errorf("apply migration %d: %w", v, err)
		}
		if _, err := tx.Exec(`INSERT INTO schema_migrations (version, applied_at) VALUES (?, ?)`, v, now()); err != nil {
			tx.Rollback()
			return fmt.Errorf("record migration %d: %w", v, err)
		}
		if err := tx.Commit(); err != nil {
			return err
		}
	}
	return nil
}

func now() string { return time.Now().UTC().Format(time.RFC3339Nano) }

// InsertEvent persists an event. Dedup key: metadata.source_event_id when
// present, otherwise a hash of the payload — delivery is at-least-once
// (webhook retries, poller overlap), so the same thing happening twice must
// be recognized as one event. Duplicates are reported, not silently
// swallowed: the trace says "duplicate" and the caller decides what that
// means.
func (d *DB) InsertEvent(e event.Event) (*EventRecord, error) {
	data, _ := json.Marshal(e.Data)
	meta, _ := json.Marshal(e.Metadata)
	dedup := ""
	if v, ok := e.Metadata["source_event_id"]; ok {
		dedup = fmt.Sprint(v)
	}
	if dedup == "" {
		h := sha256.New()
		fmt.Fprint(h, e.Type, "\x00", e.Subject, "\x00", string(data))
		dedup = hex.EncodeToString(h.Sum(nil))
	}

	res, err := d.Exec(`INSERT INTO events (id, type, source, subject, event_time, ingest_time, data, metadata, dedup_key)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(source, dedup_key) DO NOTHING`,
		e.ID, e.Type, e.Source, e.Subject, e.Timestamp.Format(time.RFC3339Nano), now(), data, meta, dedup)
	if err != nil {
		return nil, fmt.Errorf("insert event %s: %w", e.ID, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return nil, fmt.Errorf("insert event %s: %w", e.ID, err)
	}
	if n == 0 {
		return &EventRecord{Event: e, Duplicate: true}, nil
	}
	return &EventRecord{Event: e}, nil
}

func (d *DB) InsertDecision(dec event.Decision) error {
	result, _ := json.Marshal(dec.Result)
	_, err := d.Exec(`INSERT INTO decisions (id, event_id, interpreter, model, status, result, latency_ms, error, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		dec.ID, dec.EventID, dec.Interpreter, dec.Model, dec.Status, result, dec.LatencyMs, dec.Error, now())
	if err != nil {
		return fmt.Errorf("insert decision %s: %w", dec.ID, err)
	}
	return nil
}

func (d *DB) InsertExecution(id, eventID, decisionID, outcome, adapter, status, errMsg string) error {
	// decisionID may be empty for outcomes that produce no Decision
	// (filter-excluded events). The column is a foreign key, so empty
	// maps to NULL: an empty string would be a dangling reference.
	var decID any
	if decisionID != "" {
		decID = decisionID
	}
	_, err := d.Exec(`INSERT INTO executions (id, event_id, decision_id, outcome, adapter, status, error, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		id, eventID, decID, outcome, adapter, status, errMsg, now())
	if err != nil {
		return fmt.Errorf("insert execution %s: %w", id, err)
	}
	return nil
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"strconv"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/storage"
)

func events(args []string) error {
	fs := flag.NewFlagSet("mrmr events", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	unlabeled := fs.Bool("unlabeled", false, "show only events without a human label")
	limit := fs.Int("limit", 20, "maximum events to show")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if *limit < 1 || *limit > 1000 {
		return fmt.Errorf("events limit must be between 1 and 1000")
	}

	_, db, err := openConfigDB(*configPath)
	if err != nil {
		return err
	}
	defer db.Close()
	rows, err := db.ListEvents(*limit, *unlabeled)
	if err != nil {
		return err
	}
	enc := json.NewEncoder(os.Stdout)
	for _, row := range rows {
		if err := enc.Encode(row); err != nil {
			return fmt.Errorf("write events: %w", err)
		}
	}
	return nil
}

func label(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("usage: mrmr label EVENT_ID -category CATEGORY -requires-action=true|false -outcome ignore|notify")
	}
	eventID := args[0]
	fs := flag.NewFlagSet("mrmr label", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	category := fs.String("category", "", "expected category")
	requiresActionText := fs.String("requires-action", "", "whether action is required: true or false")
	outcome := fs.String("outcome", "", "expected outcome: ignore or notify")
	if err := fs.Parse(args[1:]); err != nil {
		return err
	}
	if *category == "" || *requiresActionText == "" || *outcome == "" {
		return fmt.Errorf("category, requires-action, and outcome are required")
	}
	requiresAction, err := strconv.ParseBool(*requiresActionText)
	if err != nil {
		return fmt.Errorf("requires-action must be true or false")
	}

	cfg, db, err := openConfigDB(*configPath)
	if err != nil {
		return err
	}
	defer db.Close()
	if err := validateLabelCategory(cfg, *category); err != nil {
		return err
	}
	stored, err := db.LabelEvent(eventID, *category, requiresAction, *outcome)
	if err != nil {
		return err
	}
	return json.NewEncoder(os.Stdout).Encode(stored)
}

func dataset(args []string) error {
	if len(args) == 0 || args[0] != "export" {
		return fmt.Errorf("usage: mrmr dataset export [-config mrmr.yaml] [-output path|-]")
	}
	fs := flag.NewFlagSet("mrmr dataset export", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	output := fs.String("output", "-", "output JSONL path, or - for stdout")
	if err := fs.Parse(args[1:]); err != nil {
		return err
	}

	_, db, err := openConfigDB(*configPath)
	if err != nil {
		return err
	}
	defer db.Close()
	rows, err := db.LabeledEvents()
	if err != nil {
		return err
	}

	var out io.Writer = os.Stdout
	var file *os.File
	if *output != "-" {
		file, err = os.OpenFile(*output, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o600)
		if err != nil {
			return fmt.Errorf("create dataset %s: %w", *output, err)
		}
		defer file.Close()
		out = file
	}
	if err := writeDataset(out, rows); err != nil {
		return err
	}
	fmt.Fprintf(os.Stderr, "exported %d labeled events\n", len(rows))
	return nil
}

func openConfigDB(path string) (*config.Config, *storage.DB, error) {
	cfg, err := config.Load(path)
	if err != nil {
		return nil, nil, err
	}
	db, err := storage.Open(cfg.DB.Path)
	if err != nil {
		return nil, nil, err
	}
	return cfg, db, nil
}

func validateLabelCategory(cfg *config.Config, category string) error {
	field, ok := cfg.Interpret.Schema["category"]
	if !ok || field.Type != "string" {
		return fmt.Errorf("labeling requires string interpret.schema field %q", "category")
	}
	if len(field.Enum) == 0 {
		return nil
	}
	for _, allowed := range field.Enum {
		if fmt.Sprint(allowed) == category {
			return nil
		}
	}
	return fmt.Errorf("category %q is not allowed by interpret.schema", category)
}

func writeDataset(w io.Writer, rows []storage.LabeledEvent) error {
	enc := json.NewEncoder(w)
	for _, row := range rows {
		tc := evalCase{Name: row.Event.ID, Event: row.Event}
		tc.Expected.Category = row.Label.Category
		tc.Expected.RequiresAction = new(bool)
		*tc.Expected.RequiresAction = row.Label.RequiresAction
		tc.Expected.Outcome = row.Label.ExpectedOutcome
		if err := enc.Encode(tc); err != nil {
			return fmt.Errorf("write dataset: %w", err)
		}
	}
	return nil
}

// Package filter applies deterministic checks to Events before any model
// call. It is the pipeline's cost gate (IMPLEMENTATION.md section 3):
// events that ordinary code can already exclude must not spend inference.
// Evaluation is pure: no I/O, no clock, no model. A filter can never
// fail in a way a model can, which is what makes the excluded path safe
// by construction.
//
// Two rules shape this package.
//
// Fail toward ignore. The filter is the only gate before policy, and
// policy is what authorizes outcomes. An event that cannot be resolved
// (missing field, malformed path, incomparable type) fails every
// comparison and is excluded, never passed by default. A malformed
// event that slips past the gate is one good model day from an outcome
// nobody authorized.
//
// Reasons are value-free. Failure reasons flow into the trace, the HTTP
// response, and stdout, and event payloads may be sensitive. A reason
// carries the rule index, field path, and operator only.
//
// This package does not reuse policy's comparisons on purpose. Filter
// ops are named (eq, neq) and compared by strict semantic type; policy
// conditions are operator-expression strings compared by fmt.Sprint.
// The gate is where a type-shifted value becomes a bypass, so it must
// not inherit the looser semantics. If a future third caller really
// shares one of these semantics, extract a neutral condition package
// then, not before.
package filter

import (
	"fmt"
	"math"
	"reflect"
	"strings"

	"github.com/heath0xff/mrmr/internal/event"
)

// Op is the comparison a Spec applies. v0.1 ships only the two
// comparisons the spec documents for filters: neq (excluding known
// senders such as bots) and eq, which is also the default when op is
// left empty. Numeric ordering lands when a real flow needs it; the
// Spec shape does not change.
type Op string

const (
	OpEq  Op = "eq"
	OpNeq Op = "neq"
)

// Spec is one filter line. All Specs in a List are ANDed, mirroring
// policy's condition semantics: alternatives are separate Specs, not OR.
type Spec struct {
	Field string `yaml:"field"`
	Op    Op     `yaml:"op"`
	Value any    `yaml:"value"`
}

// List is the ordered set of Specs. An empty list passes every event, so
// a config without a filter section behaves exactly as before.
type List []Spec

// fieldRoots are the only path roots a Spec may address. They are the
// Event's top-level fields, with data and metadata open to dot descent.
var fieldRoots = map[string]bool{
	"type":     true,
	"source":   true,
	"subject":  true,
	"data":     true,
	"metadata": true,
}

// normalizePath reduces a Spec's field to its canonical form and reports
// whether it addresses a value the runtime can compare. The spec
// documents both "data.author" (section 3) and "event.data.author" (the
// flow example); exactly one leading "event." is accepted, so both forms
// behave identically. Everything else is rejected at config time because
// a filter that can never match is a typo, not a choice: unknown roots,
// a bare data/metadata (a map can never compare), and sub-paths under
// scalar roots (a scalar can never have children).
func normalizePath(field string) (string, error) {
	if field == "" {
		return "", fmt.Errorf("field is required")
	}
	if strings.HasPrefix(field, "event.") {
		field = field[len("event."):]
	}
	parts := strings.Split(field, ".")
	for _, p := range parts {
		if p == "" {
			return "", fmt.Errorf("field %q: empty path segment", field)
		}
	}
	root := parts[0]
	if !fieldRoots[root] {
		return "", fmt.Errorf("field %q: unknown root %q (want type, source, subject, data, or metadata)", field, root)
	}
	switch root {
	case "type", "source", "subject":
		if len(parts) > 1 {
			return "", fmt.Errorf("field %q: %s has no sub-paths", field, root)
		}
	default:
		if len(parts) == 1 {
			return "", fmt.Errorf("field %q: %s requires a sub-path", field, root)
		}
	}
	return field, nil
}

// Validate reports whether the Spec can run correctly. Config calls it
// for every filter line, so a malformed filter refuses startup rather
// than mis-firing at request time.
func (s Spec) Validate() error {
	if _, err := normalizePath(s.Field); err != nil {
		return err
	}
	switch s.Op {
	case "", OpEq, OpNeq:
	default:
		return fmt.Errorf("op %q not supported (v0.1: eq, neq)", s.Op)
	}
	if s.Value == nil {
		return fmt.Errorf("field %q: value is required", s.Field)
	}
	if !valueOK(s.Value) {
		return fmt.Errorf("field %q: value must be a string, number, or boolean", s.Field)
	}
	return nil
}

// Evaluate reports whether e passes every Spec in order, and returns the
// first failure as a value-free reason (rule index, path, operator) for
// the trace. ok is true when the list is empty or every Spec passes.
func (l List) Evaluate(e event.Event) (bool, string) {
	for i, s := range l {
		path, err := normalizePath(s.Field)
		if err != nil {
			// Unreachable after config validation; fail closed anyway.
			// A Spec that cannot be parsed must exclude, not pass.
			return false, fmt.Sprintf("filter %d: malformed field", i+1)
		}
		got, present := resolve(e, path)
		if !present {
			// A missing field fails every operator, including neq: the
			// event cannot prove itself acceptable to the gate, and
			// exclusion is the only safe answer.
			return false, fmt.Sprintf("filter %d: field %s not present", i+1, path)
		}
		if !matches(s.Op, s.Value, got) {
			return false, fmt.Sprintf("filter %d: %s (%s) did not match", i+1, path, opName(s.Op))
		}
	}
	return true, ""
}

func opName(op Op) string {
	if op == "" {
		return string(OpEq)
	}
	return string(op)
}

// resolve walks a normalized dot path against the Event. Scalar roots
// resolve exactly; data and metadata descend into maps. Every miss
// (unknown key, a non-map mid-path, a map at the end, an empty scalar
// root) is "not present": resolution never guesses. Subject is
// optional, so an empty subject is not present. The same guard applies
// to type and source because Ingest can be called outside the HTTP
// handler, which is the only place that requires them non-empty.
func resolve(e event.Event, path string) (any, bool) {
	parts := strings.Split(path, ".")
	switch parts[0] {
	case "type":
		if e.Type != "" {
			return e.Type, true
		}
	case "source":
		if e.Source != "" {
			return e.Source, true
		}
	case "subject":
		if e.Subject != "" {
			return e.Subject, true
		}
	case "data":
		return walk(e.Data, parts[1:])
	case "metadata":
		return walk(e.Metadata, parts[1:])
	}
	return nil, false
}

// walk descends one level at a time. It is only called with a non-empty
// parts slice: normalizePath rejects a bare data/metadata root.
func walk(m map[string]any, parts []string) (any, bool) {
	cur, ok := m[parts[0]]
	if !ok {
		return nil, false
	}
	if len(parts) == 1 {
		return cur, true
	}
	next, ok := cur.(map[string]any)
	if !ok {
		return nil, false
	}
	return walk(next, parts[1:])
}

// kind is a value's semantic type. Anything that is not a number,
// string, or bool (nil, maps, slices) is opaque and comparable with
// nothing.
type kind int

const (
	kindNumber kind = iota
	kindString
	kindBool
	kindOpaque
)

func classify(v any) kind {
	switch v.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:
		return kindNumber
	case string:
		return kindString
	case bool:
		return kindBool
	}
	return kindOpaque
}

// toFloat normalizes a numeric value to float64, reporting whether the
// result is usable for a comparison. Non-finite inputs (NaN, Inf) are
// not comparable: NaN never equals itself, so an eq check can never
// match and a neq check would pass every value, malformed data
// included. They are reported incomparable instead of compared.
func toFloat(v any) (float64, bool) {
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return float64(rv.Int()), true
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return float64(rv.Uint()), true
	case reflect.Float32, reflect.Float64:
		f := rv.Float()
		return f, finite(f)
	}
	return 0, false // classify() guarantees a number here
}

// valueOK reports whether a Spec value can ever take part in a
// comparison. The comparator works on three semantic types: number,
// string, bool. Anything else (lists, maps, channels) can never
// match, and a filter line that can never match is a typo, not a
// choice: it must fail startup, not silently exclude every event at
// runtime. Numbers must be finite: NaN never equals itself, so it can
// never satisfy eq and would pass neq against every value; Inf is not
// a value a source will send. Both are unmatchable by construction.
func valueOK(v any) bool {
	switch n := v.(type) {
	case string, bool:
		return true
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return true
	case float32:
		return finite(float64(n))
	case float64:
		return finite(n)
	}
	return false
}

// finite reports whether a number can take part in a comparison.
// Shared by valueOK (config side) and toFloat (event side) so the
// non-finite rule has one definition.
func finite(f float64) bool {
	return !math.IsNaN(f) && !math.IsInf(f, 0)
}

// compare reports whether two values are equal, and whether they are
// comparable at all. Comparison is strict by semantic type on purpose,
// and intentionally stricter than policy.match's fmt.Sprint semantics:
// at the gate, a type-shifted value (the number 5 where a string is
// expected, "true" where a bool is expected) must not satisfy neq and
// slide past the gate. Numeric values normalize across int and float
// representations because YAML decodes 5 as int and JSON decodes it as
// float64: the same number, two sources. Values of different kinds are
// incomparable.
func compare(want, got any) (equal, comparable bool) {
	k := classify(want)
	if k != classify(got) || k == kindOpaque {
		return false, false
	}
	switch k {
	case kindNumber:
		w, wok := toFloat(want)
		g, gok := toFloat(got)
		if !wok || !gok {
			return false, false
		}
		return w == g, true
	case kindString:
		return want.(string) == got.(string), true
	case kindBool:
		return want.(bool) == got.(bool), true
	}
	return false, false
}

// matches applies the operator. An incomparable pair fails for both eq
// and neq: the event is excluded either way, and the trace says which
// check excluded it.
func matches(op Op, want, got any) bool {
	equal, comparable := compare(want, got)
	if !comparable {
		return false
	}
	if op == OpNeq {
		return !equal
	}
	return equal
}

package main

import (
	"bufio"
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/model"
)

type evalCase struct {
	Name     string      `json:"name"`
	Event    event.Event `json:"event"`
	Expected struct {
		Category       string `json:"category"`
		RequiresAction *bool  `json:"requires_action"`
		Outcome        string `json:"outcome"`
	} `json:"expected"`
}

type evalSummary struct {
	Total             int     `json:"total"`
	ValidDecisions    int     `json:"valid_decisions"`
	CategoryCorrect   int     `json:"category_correct"`
	CategoryAccuracy  float64 `json:"category_accuracy"`
	ActionCorrect     int     `json:"requires_action_correct"`
	ActionAccuracy    float64 `json:"requires_action_accuracy"`
	OutcomeCorrect    int     `json:"outcome_correct"`
	OutcomeAccuracy   float64 `json:"outcome_accuracy"`
	ExpectedNonIgnore int     `json:"expected_non_ignore"`
	FalseIgnores      int     `json:"false_ignores"`
	FalseIgnoreRate   float64 `json:"false_ignore_rate"`
}

func eval(args []string) error {
	fs := flag.NewFlagSet("mrmr eval", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	datasetPath := fs.String("dataset", "testdata/generated-eval.jsonl", "path to labeled JSONL dataset")
	if err := fs.Parse(args); err != nil {
		return err
	}

	cfg, err := config.Load(*configPath)
	if err != nil {
		return err
	}
	if f, ok := cfg.Interpret.Schema["category"]; !ok || f.Type != "string" {
		return fmt.Errorf("eval requires string interpret.schema field %q", "category")
	}
	if f, ok := cfg.Interpret.Schema["requires_action"]; !ok || f.Type != "boolean" {
		return fmt.Errorf("eval requires boolean interpret.schema field %q", "requires_action")
	}
	cases, err := loadEvalCases(*datasetPath)
	if err != nil {
		return err
	}

	summary := evaluate(context.Background(), cfg, cases, os.Stderr)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	return enc.Encode(summary)
}

func loadEvalCases(path string) ([]evalCase, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open dataset %s: %w", path, err)
	}
	defer f.Close()

	var cases []evalCase
	s := bufio.NewScanner(f)
	s.Buffer(make([]byte, 64*1024), 1<<20)
	for line := 1; s.Scan(); line++ {
		if len(s.Bytes()) == 0 {
			continue
		}
		var tc evalCase
		if err := json.Unmarshal(s.Bytes(), &tc); err != nil {
			return nil, fmt.Errorf("parse dataset %s line %d: %w", path, line, err)
		}
		if tc.Name == "" || tc.Event.Type == "" || tc.Event.Source == "" || tc.Expected.Category == "" || tc.Expected.RequiresAction == nil {
			return nil, fmt.Errorf("parse dataset %s line %d: name, event type/source, category, and requires_action are required", path, line)
		}
		if tc.Expected.Outcome != "ignore" && tc.Expected.Outcome != "notify" {
			return nil, fmt.Errorf("parse dataset %s line %d: outcome must be ignore or notify", path, line)
		}
		cases = append(cases, tc)
	}
	if err := s.Err(); err != nil {
		return nil, fmt.Errorf("read dataset %s: %w", path, err)
	}
	if len(cases) == 0 {
		return nil, fmt.Errorf("dataset %s is empty", path)
	}
	return cases, nil
}

func evaluate(ctx context.Context, cfg *config.Config, cases []evalCase, progress io.Writer) evalSummary {
	summary := evalSummary{Total: len(cases)}
	client := &model.Client{}
	for i, tc := range cases {
		e := tc.Event
		e.ID = fmt.Sprintf("eval_%03d", i+1)
		e.Timestamp = time.Date(2026, time.January, 1, 12, 0, 0, 0, time.UTC)
		payload, _ := json.Marshal(e)
		result, _, _, err := client.Interpret(ctx, cfg.Models[cfg.Interpret.Model], cfg.Interpret.Model, cfg.Interpret.Prompt, cfg.Interpret.Schema, payload)

		category, requiresAction, outcome := "", false, "ignore"
		if err == nil {
			summary.ValidDecisions++
			category, _ = result["category"].(string)
			requiresAction, _ = result["requires_action"].(bool)
			then, _ := cfg.Policy.Evaluate(result)
			outcome = then.Outcome()
		}

		categoryOK := err == nil && category == tc.Expected.Category
		actionOK := err == nil && requiresAction == *tc.Expected.RequiresAction
		outcomeOK := err == nil && outcome == tc.Expected.Outcome
		if categoryOK {
			summary.CategoryCorrect++
		}
		if actionOK {
			summary.ActionCorrect++
		}
		if outcomeOK {
			summary.OutcomeCorrect++
		}
		if tc.Expected.Outcome != "ignore" {
			summary.ExpectedNonIgnore++
			if outcome == "ignore" {
				summary.FalseIgnores++
			}
		}

		if err != nil {
			fmt.Fprintf(progress, "[%d/%d] ERROR %s: %v\n", i+1, len(cases), tc.Name, err)
		} else if categoryOK && actionOK && outcomeOK {
			fmt.Fprintf(progress, "[%d/%d] PASS  %s\n", i+1, len(cases), tc.Name)
		} else {
			fmt.Fprintf(progress, "[%d/%d] FAIL  %s: got category=%s requires_action=%t outcome=%s\n", i+1, len(cases), tc.Name, category, requiresAction, outcome)
		}
	}

	summary.CategoryAccuracy = ratio(summary.CategoryCorrect, summary.Total)
	summary.ActionAccuracy = ratio(summary.ActionCorrect, summary.Total)
	summary.OutcomeAccuracy = ratio(summary.OutcomeCorrect, summary.Total)
	summary.FalseIgnoreRate = ratio(summary.FalseIgnores, summary.ExpectedNonIgnore)
	return summary
}

func ratio(n, total int) float64 {
	if total == 0 {
		return 0
	}
	return float64(n) / float64(total)
}

// Package source hosts source adapters: the code that watches the outside
// world and emits normalized Events. v0.1's only ingress was POST /api/events;
// the HTTP poller adds pull-based ingestion for feeds and APIs that have no
// webhooks. A poller is deliberately dumb: it fetches, normalizes items into
// Events, and hands each one to the ordinary Ingest pipeline — it never
// interprets, filters, or routes.
//
// Concurrency contract: one goroutine per source, owned by Run, bounded by
// the context, exited when the context is canceled. Polls within one source
// are strictly serial, so cursor state needs no locking beyond SQLite's.
package source

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

// HTTPPoller polls a JSON endpoint on an interval and ingests each record
// as an Event. Cursor semantics are lazy on purpose: every item is offered
// to InsertEvent on every poll and dedup drops what was seen, so correctness
// never depends on ordering assumptions. The persisted cursor exists for
// cursor-based APIs (URL substitution) and as a restart watermark, not as
// the dedup mechanism.
type HTTPPoller struct {
	cfg    config.Source
	urlTpl *template.Template
	client *http.Client
	// bearer is resolved once from the environment at construction; it is
	// never persisted, logged, or copied anywhere but the request header.
	bearer string
}

// NewHTTPPoller validates and prepares a poller. The bearer token is read
// from the environment once, here: it must exist at startup (fail loudly)
// and must never be persisted or logged.
func NewHTTPPoller(cfg config.Source) (*HTTPPoller, error) {
	tpl, err := template.New("url").Parse(cfg.URL)
	if err != nil {
		return nil, fmt.Errorf("source %s: bad url template: %w", cfg.Name, err)
	}
	bearer, err := bearerFromEnv(cfg.BearerTokenEnv)
	if err != nil {
		return nil, fmt.Errorf("source %s: %w", cfg.Name, err)
	}
	return &HTTPPoller{
		cfg:    cfg,
		urlTpl: tpl,
		// Outbound polls must be bounded: a hung target must not stall the
		// poll loop's single goroutine forever.
		client: &http.Client{Timeout: 15 * time.Second},
		bearer: bearer,
	}, nil
}

// Run polls until ctx is canceled. The first poll is immediate so a fresh
// config produces data without waiting one interval.
func (p *HTTPPoller) Run(ctx context.Context, rt *runtime.Runtime) {
	ticker := time.NewTicker(p.cfg.Every)
	defer ticker.Stop()

	p.poll(ctx, rt)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			p.poll(ctx, rt)
		}
	}
}

// poll is one fetch-normalize-ingest cycle. Every error path is a log line,
// never a crash: a broken feed must not take down the runtime, and the next
// tick retries anyway.
func (p *HTTPPoller) poll(ctx context.Context, rt *runtime.Runtime) {
	// If the fetch itself is canceled by shutdown, nothing was ingested and
	// the cursor is unchanged — safe to abandon mid-flight.
	items, err := p.fetch(ctx, rt.DB)
	if err != nil {
		log.Printf("mrmr: poll %s: fetch failed: %v", p.cfg.Name, err)
		return
	}

	var ingested, dups, cursorAdvanced int
	newCursor := ""
	for i, item := range items {
		if ctx.Err() != nil {
			return // shutdown: remaining items wait for the next poll
		}
		obj, ok := item.(map[string]any)
		if !ok {
			log.Printf("mrmr: poll %s: item %d is not an object, skipped", p.cfg.Name, i)
			continue
		}
		if c := cursorValue(obj, p.cfg.CursorField); c != "" {
			if c > newCursor { // ponytail: string max; numeric ordering only matters for {{.cursor}} substitution
				newCursor = c
			}
		}
		e, err := p.normalize(obj)
		if err != nil {
			log.Printf("mrmr: poll %s: item %d: %v", p.cfg.Name, i, err)
			continue
		}
		resp, err := rt.Ingest(ctx, e)
		if err != nil {
			log.Printf("mrmr: poll %s: ingest %s failed: %v", p.cfg.Name, e.ID, err)
			continue
		}
		if resp.Duplicate {
			dups++
		} else {
			ingested++
		}
	}

	// Advance the watermark only after the batch is offered: a crash
	// mid-poll re-polls the same window, and dedup makes that harmless.
	if newCursor != "" && newCursor != p.cursor(rt.DB) {
		if err := rt.DB.SetCursor(p.cfg.Name, newCursor); err != nil {
			log.Printf("mrmr: poll %s: persist cursor failed: %v", p.cfg.Name, err)
		} else {
			cursorAdvanced = 1
		}
	}
	log.Printf("mrmr: poll %s: %d items: %d new, %d duplicate, cursor=%s",
		p.cfg.Name, len(items), ingested, dups, map[bool]string{true: newCursor, false: "unchanged"}[cursorAdvanced == 1])
}

// fetch retrieves and extracts the item array. The cursor is substituted
// into the URL template when present so cursor-based APIs page correctly;
// plain feeds ignore it.
func (p *HTTPPoller) fetch(ctx context.Context, db *storage.DB) ([]any, error) {
	var urlBuf bytes.Buffer
	if err := p.urlTpl.Execute(&urlBuf, map[string]any{"cursor": p.cursor(db)}); err != nil {
		return nil, fmt.Errorf("render url: %w", err)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, urlBuf.String(), nil)
	if err != nil {
		return nil, err
	}
	if p.bearer != "" {
		req.Header.Set("Authorization", "Bearer "+p.bearer)
	}
	resp, err := p.client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	// Feeds are small; 4 MiB caps a hostile or misconfigured target.
	body, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if err != nil {
		return nil, err
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return nil, fmt.Errorf("status %d", resp.StatusCode)
	}

	var doc any
	if err := json.Unmarshal(body, &doc); err != nil {
		return nil, fmt.Errorf("decode JSON: %w", err)
	}
	items := doc
	if p.cfg.ItemPath != "" {
		items = doc
		for _, part := range strings.Split(p.cfg.ItemPath, ".") {
			m, ok := items.(map[string]any)
			if !ok {
				return nil, fmt.Errorf("item_path %q: %s is not an object", p.cfg.ItemPath, part)
			}
			items = m[part]
		}
	}
	list, ok := items.([]any)
	if !ok {
		if items == nil {
			return nil, nil // absent path is an empty poll, not an error
		}
		return nil, fmt.Errorf("item_path %q did not resolve to an array", p.cfg.ItemPath)
	}
	return list, nil
}

// normalize turns one fetched record into an Event. The whole record becomes
// data — the core makes no assumptions about source payloads, and dropping
// fields here would silently erase exactly the context the interpreter needs.
// The cursor field doubles as source_event_id, which is what makes dedup work.
func (p *HTTPPoller) normalize(item map[string]any) (event.Event, error) {
	e := event.Event{
		ID:        event.NewID("evt_"),
		Type:      p.cfg.EventType,
		Source:    p.cfg.Name,
		Timestamp: time.Now().UTC(),
		Data:      item,
	}
	if p.cfg.SubjectField != "" {
		if v, ok := item[p.cfg.SubjectField]; ok {
			e.Subject = fmt.Sprint(v)
		}
	}
	if p.cfg.TimestampField != "" {
		if v, ok := item[p.cfg.TimestampField].(string); ok {
			if ts, perr := time.Parse(time.RFC3339, v); perr == nil {
				e.Timestamp = ts.UTC()
			}
			// Unparseable timestamps keep "now": a wrong-but-present event
			// beats a dropped one for ambient feeds.
		}
	}
	if p.cfg.CursorField != "" {
		if c := cursorValue(item, p.cfg.CursorField); c != "" {
			e.Metadata = map[string]any{"source_event_id": c}
		} else {
			return e, fmt.Errorf("cursor_field %q missing; item cannot be deduplicated", p.cfg.CursorField)
		}
	}
	return e, nil
}

func cursorValue(item map[string]any, field string) string {
	if field == "" {
		return ""
	}
	if v, ok := item[field]; ok {
		return fmt.Sprint(v)
	}
	return ""
}

// cursor reads the persisted watermark. An unknown source is a fresh poller:
// empty cursor, and the URL template renders without one.
func (p *HTTPPoller) cursor(db *storage.DB) string {
	c, err := db.Cursor(p.cfg.Name)
	if err != nil {
		log.Printf("mrmr: poll %s: read cursor: %v", p.cfg.Name, err)
	}
	return c
}

// bearerFromEnv resolves the bearer_token_env reference at startup.
func bearerFromEnv(name string) (string, error) {
	if name == "" {
		return "", nil
	}
	v, ok := os.LookupEnv(name)
	if !ok || v == "" {
		return "", fmt.Errorf("env %s (bearer_token_env) is not set", name)
	}
	return v, nil
}

// Poller tests run the full loop against real HTTP servers: a feed server
// standing in for the polled target and the standard mock OpenAI-compatible
// model behind a real SQLite database. The invariants that matter: items
// become events exactly once across repeated polls (dedup, not the cursor,
// is the correctness mechanism), the cursor is persisted and substituted
// into subsequent fetches, and malformed items are skipped without killing
// the poll.
package source

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"sync/atomic"
	"testing"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

// modelMock returns the standard canned OpenAI-compatible response. Every
// ingested item scores unimportant so the pipeline ends in ignore and the
// tests stay quiet.
func modelMock(t *testing.T) (url string, calls *atomic.Int32) {
	t.Helper()
	var n atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n.Add(1)
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]any{
			"choices": []any{map[string]any{
				"message": map[string]any{"content": `{"category":"unimportant","importance":0.1}`},
			}},
		})
	}))
	t.Cleanup(srv.Close)
	return srv.URL, &n
}

func testRuntime(t *testing.T, modelURL string) *runtime.Runtime {
	t.Helper()
	db, err := storage.Open(filepath.Join(t.TempDir(), "poller.db"))
	if err != nil {
		t.Fatalf("open storage: %v", err)
	}
	t.Cleanup(func() { db.Close() })
	return &runtime.Runtime{
		DB:       db,
		Client:   &model.Client{},
		ModelCfg: model.Config{Provider: "openai-compatible", BaseURL: modelURL, Model: "mock-model"},
		ModelKey: "mock",
		Prompt:   "classify this event",
		Schema: model.Schema{
			"category":   {Type: "string", Enum: []any{"unimportant"}},
			"importance": {Type: "number"},
		},
		Policy: mustPolicy(),
	}
}

// mustPolicy keeps the struct literal out of every test runtime construction.
func mustPolicy() policy.Policy {
	return policy.Policy{Default: policy.Then{Ignore: true}}
}

func pollerCfg(url string) config.Source {
	return config.Source{
		Name:        "feed",
		Type:        "http-poller",
		URL:         url,
		Every:       time.Minute, // Run is never entered in tests; poll is called directly
		ItemPath:    "items",
		CursorField: "id",
		EventType:   "feed.item.published",
	}
}

func feedServer(t *testing.T, pages ...string) (url string, gotQuery *atomic.Value) {
	t.Helper()
	var n atomic.Int32
	var q atomic.Value
	q.Store("")
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		i := int(n.Add(1)) - 1
		q.Store(r.URL.RawQuery)
		page := pages[len(pages)-1]
		if i < len(pages) {
			page = pages[i]
		}
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, page)
	}))
	t.Cleanup(srv.Close)
	return srv.URL, &q
}

func countEvents(t *testing.T, rt *runtime.Runtime) int {
	t.Helper()
	var n int
	if err := rt.DB.QueryRow(`SELECT COUNT(*) FROM events`).Scan(&n); err != nil {
		t.Fatalf("count events: %v", err)
	}
	return n
}

// TestPollerIngestsEachItemOnce is the core loop: two items become two
// events with a model call each; repolling the same feed adds nothing
// because dedup drops them before the model; a changed feed adds only the
// new item. The cursor must be persisted across the polls.
func TestPollerIngestsEachItemOnce(t *testing.T) {
	modelURL, modelCalls := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[
		{"id":"a","title":"first"},
		{"id":"b","title":"second"}]}`,
		`{"items":[
		{"id":"a","title":"first"},
		{"id":"b","title":"second"},
		{"id":"c","title":"third"}]}`)

	rt := testRuntime(t, modelURL)
	p, err := NewHTTPPoller(pollerCfg(feedURL))
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}
	ctx := context.Background()

	p.poll(ctx, rt)
	if got := countEvents(t, rt); got != 2 {
		t.Errorf("events after first poll = %d, want 2", got)
	}
	if modelCalls.Load() != 2 {
		t.Errorf("model calls after first poll = %d, want 2", modelCalls.Load())
	}
	if c, _ := rt.DB.Cursor("feed"); c != "b" {
		t.Errorf("cursor after first poll = %q, want b", c)
	}

	p.poll(ctx, rt)
	if got := countEvents(t, rt); got != 3 {
		t.Errorf("events after second poll = %d, want 3 (only the new item)", got)
	}
	// Dedup happens at InsertEvent, before any model call — repolling a
	// known feed must cost no inference.
	if modelCalls.Load() != 3 {
		t.Errorf("model calls after second poll = %d, want 3", modelCalls.Load())
	}
	if c, _ := rt.DB.Cursor("feed"); c != "c" {
		t.Errorf("cursor after second poll = %q, want c", c)
	}
}

// TestPollerSubstitutesCursorIntoURL pins the cursor-based-API case: the
// first fetch has no cursor, later fetches carry the persisted one.
func TestPollerSubstitutesCursorIntoURL(t *testing.T) {
	modelURL, _ := modelMock(t)
	feedURL, gotQuery := feedServer(t, `{"items":[{"id":"a"}]}`)

	rt := testRuntime(t, modelURL)
	cfg := pollerCfg(feedURL + "?after={{ .cursor }}")
	p, err := NewHTTPPoller(cfg)
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}

	p.poll(context.Background(), rt)
	if q := gotQuery.Load().(string); q != "after=" {
		t.Errorf("first poll query = %q, want empty after", q)
	}
	p.poll(context.Background(), rt)
	if q := gotQuery.Load().(string); q != "after=a" {
		t.Errorf("second poll query = %q, want after=a", q)
	}
}

// TestPollerNormalizesItemFields covers the mapping knobs: subject and
// RFC3339 timestamp come from the item, source_event_id comes from the
// cursor field, and the whole item is preserved as data.
func TestPollerNormalizesItemFields(t *testing.T) {
	modelURL, _ := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[
		{"id":"x1","title":"Disk full","published":"2026-09-07T12:00:00Z","disk":"nvme0"}]}`)

	rt := testRuntime(t, modelURL)
	cfg := pollerCfg(feedURL)
	cfg.SubjectField = "title"
	cfg.TimestampField = "published"
	p, err := NewHTTPPoller(cfg)
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}

	p.poll(context.Background(), rt)
	// QueryRow, not Query: the pool is a single connection (SetMaxOpenConns(1)),
	// so an open rows iterator would deadlock Inspect below.
	var id string
	if err := rt.DB.QueryRow(`SELECT id FROM events WHERE source = 'feed' LIMIT 1`).Scan(&id); err != nil {
		t.Fatalf("query event: %v", err)
	}
	ins, err := rt.DB.Inspect(id)
	if err != nil {
		t.Fatalf("inspect: %v", err)
	}
	e := ins.Event
	if e.Subject != "Disk full" {
		t.Errorf("subject = %q, want Disk full", e.Subject)
	}
	if e.Type != "feed.item.published" {
		t.Errorf("type = %q, want feed.item.published", e.Type)
	}
	if want := time.Date(2026, 9, 7, 12, 0, 0, 0, time.UTC); !e.Timestamp.Equal(want) {
		t.Errorf("timestamp = %v, want item's %v", e.Timestamp, want)
	}
	if e.Data["disk"] != "nvme0" {
		t.Errorf("data = %v, want the whole item preserved", e.Data)
	}
}

// TestPollerSkipsItemsWithoutCursorField pins the fail-closed dedup rule:
// when cursor_field is configured, an item without it cannot be identified
// and must not be ingested (payload-hash dedup would not catch a changing
// payload, so ingest would duplicate).
func TestPollerSkipsItemsWithoutCursorField(t *testing.T) {
	modelURL, modelCalls := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[
		{"title":"no id here"},
		{"id":"ok","title":"fine"}]}`)

	rt := testRuntime(t, modelURL)
	p, err := NewHTTPPoller(pollerCfg(feedURL))
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}

	p.poll(context.Background(), rt)
	if got := countEvents(t, rt); got != 1 {
		t.Errorf("events = %d, want 1 (only the identified item)", got)
	}
	if modelCalls.Load() != 1 {
		t.Errorf("model calls = %d, want 1", modelCalls.Load())
	}
}

// TestPollerFetchFailureKeepsState: a dead target must not crash, ingest
// nothing, or move the cursor; the next tick retries.
func TestPollerFetchFailureKeepsState(t *testing.T) {
	modelURL, _ := modelMock(t)
	rt := testRuntime(t, modelURL)
	rt.DB.SetCursor("feed", "old")

	p, err := NewHTTPPoller(pollerCfg("http://127.0.0.1:1/feed"))
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}
	p.poll(context.Background(), rt) // port 1: connection refused

	if got := countEvents(t, rt); got != 0 {
		t.Errorf("events = %d, want 0", got)
	}
	if c, _ := rt.DB.Cursor("feed"); c != "old" {
		t.Errorf("cursor = %q, want unchanged old", c)
	}
}

// TestCursorSurvivesReopen pins the restart-safety story: the watermark
// lives in SQLite, so a restarted runtime resumes where it left off.
func TestCursorSurvivesReopen(t *testing.T) {
	path := filepath.Join(t.TempDir(), "cursor.db")
	db1, err := storage.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := db1.SetCursor("feed", "42"); err != nil {
		t.Fatal(err)
	}
	db1.Close()

	db2, err := storage.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer db2.Close()
	if c, err := db2.Cursor("feed"); err != nil || c != "42" {
		t.Errorf("cursor after reopen = %q, %v, want 42", c, err)
	}
	if c, err := db2.Cursor("unknown"); err != nil || c != "" {
		t.Errorf("unknown source cursor = %q, %v, want empty, nil", c, err)
	}
}

// TestRunStopsOnContextCancel is the goroutine-contract check: Run owns one
// goroutine, exits when ctx is canceled, and does it promptly.
func TestRunStopsOnContextCancel(t *testing.T) {
	modelURL, _ := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[]}`)
	rt := testRuntime(t, modelURL)
	cfg := pollerCfg(feedURL)
	cfg.Every = 50 * time.Millisecond // fast ticks; feed returns no items
	p, err := NewHTTPPoller(cfg)
	if err != nil {
		t.Fatal(err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { p.Run(ctx, rt); close(done) }()
	time.Sleep(120 * time.Millisecond) // let at least one tick pass
	cancel()

	select {
	case <-done:
		// stopped promptly
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not stop after context cancel")
	}
}

// Source cursor persistence. The cursor is a per-source watermark: the
// poller's restart-safe position in a feed. It is an optimization and a
// resume point, never the dedup mechanism — dedup lives in InsertEvent's
// (source, source_event_id) key, so a lost or stale cursor can cause
// re-offering, never re-processing.
package storage

import (
	"database/sql"
	"fmt"
)

// Cursor returns the persisted watermark for a source. An unknown source is
// a fresh poller: "" and no error.
func (d *DB) Cursor(name string) (string, error) {
	var c string
	err := d.QueryRow(`SELECT cursor FROM source_cursors WHERE name = ?`, name).Scan(&c)
	if err == sql.ErrNoRows {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("read cursor %s: %w", name, err)
	}
	return c, nil
}

// SetCursor persists the watermark upsert-style: the poll loop is the only
// writer per source, so last-write-wins is correct.
func (d *DB) SetCursor(name, cursor string) error {
	_, err := d.Exec(`INSERT INTO source_cursors (name, cursor, updated_at) VALUES (?, ?, ?)
		ON CONFLICT(name) DO UPDATE SET cursor = excluded.cursor, updated_at = excluded.updated_at`,
		name, cursor, now())
	if err != nil {
		return fmt.Errorf("set cursor %s: %w", name, err)
	}
	return nil
}

